export const GAME_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\">\n  <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n  <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n  <title>Ninja Slice - Low Key Swipe Action</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@400;600;700&family=Outfit:wght@300;400;600;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --bg-dark: #090a0f;\n      --bg-card: rgba(18, 20, 32, 0.65);\n      --border-glass: rgba(255, 255, 255, 0.08);\n      --border-neon: rgba(147, 51, 234, 0.4);\n      --color-primary: #a855f7;\n      --color-primary-glow: rgba(168, 85, 247, 0.35);\n      --color-secondary: #3b82f6;\n      --color-danger: #ef4444;\n      --color-text: #f3f4f6;\n      --color-text-muted: #9ca3af;\n      --font-logo: 'Fredoka', sans-serif;\n      --font-ui: 'Outfit', sans-serif;\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      user-select: none;\n      -webkit-user-select: none;\n      -webkit-touch-callout: none;\n      touch-action: none;\n    }\n\n    body {\n      width: 100vw;\n      height: 100vh;\n      overflow: hidden;\n      background-color: var(--bg-dark);\n      color: var(--color-text);\n      font-family: var(--font-ui);\n      position: relative;\n    }\n\n    #gameCanvas {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      z-index: 1;\n      display: block;\n    }\n\n    #hud {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: auto;\n      z-index: 10;\n      padding: 24px 24px;\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      pointer-events: none;\n      font-family: var(--font-ui);\n    }\n\n    #hud.hidden {\n      display: none !important;\n    }\n\n    .hud-top-left {\n      display: flex;\n      flex-direction: column;\n    }\n\n    #scoreLabel {\n      font-size: 0.75rem;\n      letter-spacing: 0.15em;\n      font-weight: 800;\n      color: var(--color-primary);\n      text-shadow: 0 0 10px var(--color-primary-glow);\n    }\n\n    #scoreValue {\n      font-size: 2.25rem;\n      font-weight: 800;\n      line-height: 1;\n      color: #ffffff;\n    }\n\n    .hud-top-center {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 8px;\n    }\n\n    #timerContainer {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      background: rgba(0, 0, 0, 0.4);\n      padding: 6px 16px;\n      border-radius: 12px;\n      border: 1px solid rgba(255, 255, 255, 0.05);\n    }\n\n    #timerContainer.hidden {\n      display: none !important;\n    }\n\n    #timerLabel {\n      font-size: 0.65rem;\n      font-weight: 600;\n      letter-spacing: 0.1em;\n      color: var(--color-text-muted);\n    }\n\n    #timerValue {\n      font-size: 1.5rem;\n      font-weight: 800;\n      color: #fff;\n    }\n\n    #comboAnnouncer {\n      font-size: 1.75rem;\n      font-weight: 900;\n      font-family: var(--font-logo);\n      color: #facc15;\n      text-shadow: 0 2px 10px rgba(250, 204, 21, 0.5);\n      transform: scale(0);\n      transition: transform 0.15s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n    }\n\n    #comboAnnouncer.pop {\n      transform: scale(1.1) rotate(-5deg);\n    }\n\n    .hud-top-right {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      pointer-events: auto;\n    }\n\n    #livesContainer {\n      display: flex;\n      gap: 6px;\n    }\n\n    .heart {\n      width: 16px;\n      height: 16px;\n      background-color: #374151;\n      position: relative;\n      transform: rotate(-45deg);\n      transition: background-color 0.3s ease, transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n    }\n\n    .heart::before,\n    .heart::after {\n      content: \"\";\n      width: 16px;\n      height: 16px;\n      border-radius: 50%;\n      background-color: inherit;\n      position: absolute;\n    }\n\n    .heart::before {\n      top: -8px;\n      left: 0;\n    }\n\n    .heart::after {\n      top: 0;\n      left: 8px;\n    }\n\n    .heart.active {\n      background-color: var(--color-danger);\n      box-shadow: 0 0 10px rgba(239, 68, 68, 0.4);\n    }\n\n    .heart.lost {\n      transform: scale(0.6) rotate(-45deg);\n      background-color: #374151;\n      box-shadow: none;\n    }\n\n    #pauseButton {\n      width: 42px;\n      height: 42px;\n      border-radius: 50%;\n      border: 1px solid var(--border-glass);\n      background: var(--bg-card);\n      color: white;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      cursor: pointer;\n      backdrop-filter: blur(8px);\n      -webkit-backdrop-filter: blur(8px);\n      transition: background 0.2s, transform 0.1s;\n    }\n\n    #pauseButton svg {\n      width: 20px;\n      height: 20px;\n    }\n\n    #pauseButton:active {\n      transform: scale(0.9);\n      background: rgba(255, 255, 255, 0.1);\n    }\n\n    .overlay-container {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      z-index: 20;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      padding: 16px;\n      pointer-events: auto;\n    }\n\n    .menu-card {\n      width: 100%;\n      max-width: 400px;\n      background: var(--bg-card);\n      border: 1px solid var(--border-glass);\n      border-radius: 28px;\n      padding: 36px 28px;\n      text-align: center;\n      backdrop-filter: blur(20px);\n      -webkit-backdrop-filter: blur(20px);\n      box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5), inset 0 1px 1px rgba(255, 255, 255, 0.1);\n      display: flex;\n      flex-direction: column;\n      gap: 28px;\n      z-index: 25;\n      transform: scale(0.9);\n      opacity: 0;\n      pointer-events: none;\n      transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.15), opacity 0.3s ease;\n      position: absolute;\n    }\n\n    .menu-card.active {\n      transform: scale(1);\n      opacity: 1;\n      pointer-events: auto;\n      position: relative;\n    }\n\n    .menu-card.hidden {\n      display: none !important;\n    }\n\n    .logo-area {\n      position: relative;\n      margin-bottom: 8px;\n    }\n\n    .logo-title {\n      font-family: var(--font-logo);\n      font-weight: 700;\n      font-size: 3rem;\n      letter-spacing: -0.02em;\n      color: #fff;\n      line-height: 1;\n      text-shadow: 0 4px 12px rgba(0, 0, 0, 0.4);\n    }\n\n    .logo-title .highlight {\n      color: var(--color-primary);\n      text-shadow: 0 0 15px var(--color-primary-glow);\n    }\n\n    .logo-subtitle {\n      font-size: 0.85rem;\n      font-weight: 400;\n      color: var(--color-text-muted);\n      letter-spacing: 0.15em;\n      text-transform: uppercase;\n      margin-top: 6px;\n    }\n\n    .title-bg-glow {\n      position: absolute;\n      top: 50%;\n      left: 50%;\n      transform: translate(-50%, -50%);\n      width: 120px;\n      height: 120px;\n      background: var(--color-primary);\n      filter: blur(65px);\n      opacity: 0.25;\n      z-index: -1;\n      pointer-events: none;\n    }\n\n    .menu-actions {\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n      width: 100%;\n    }\n\n    .btn {\n      width: 100%;\n      padding: 16px;\n      border-radius: 16px;\n      font-family: var(--font-ui);\n      font-weight: 600;\n      font-size: 1rem;\n      letter-spacing: 0.05em;\n      border: none;\n      cursor: pointer;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      position: relative;\n      overflow: hidden;\n      transition: transform 0.15s, box-shadow 0.2s;\n    }\n\n    .btn:active {\n      transform: scale(0.96);\n    }\n\n    .btn-primary {\n      background: linear-gradient(135deg, #a855f7 0%, #7c3aed 100%);\n      color: white;\n      box-shadow: 0 4px 15px rgba(124, 58, 237, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2);\n    }\n\n    .btn-secondary {\n      background: rgba(255, 255, 255, 0.08);\n      border: 1px solid rgba(255, 255, 255, 0.08);\n      color: var(--color-text);\n      box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);\n    }\n\n    .btn-danger {\n      background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%);\n      color: white;\n      box-shadow: 0 4px 15px rgba(239, 68, 68, 0.25);\n    }\n\n    .btn-subtext {\n      font-size: 0.7rem;\n      font-weight: 400;\n      color: rgba(255, 255, 255, 0.7);\n      letter-spacing: 0;\n      margin-top: 3px;\n    }\n\n    .menu-footer {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-top: 8px;\n      gap: 12px;\n    }\n\n    .btn-icon-label {\n      background: none;\n      border: none;\n      color: var(--color-text-muted);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      font-family: var(--font-ui);\n      font-weight: 600;\n      font-size: 0.9rem;\n      cursor: pointer;\n      transition: color 0.2s;\n    }\n\n    .btn-icon-label svg {\n      width: 20px;\n      height: 20px;\n    }\n\n    .btn-icon-label:active {\n      color: #fff;\n    }\n\n    .high-score-badge {\n      background: rgba(255, 255, 255, 0.05);\n      border: 1px solid rgba(255, 255, 255, 0.05);\n      padding: 6px 14px;\n      border-radius: 20px;\n      font-size: 0.8rem;\n      font-weight: 600;\n      color: var(--color-text);\n    }\n\n    #bestScoreVal {\n      color: #facc15;\n      font-weight: 800;\n    }\n\n    .settings-content {\n      display: flex;\n      flex-direction: column;\n      gap: 20px;\n      text-align: left;\n    }\n\n    .settings-row {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      width: 100%;\n    }\n\n    .settings-row label {\n      font-weight: 600;\n      font-size: 1rem;\n    }\n\n    .btn-sm {\n      padding: 10px 14px;\n      border-radius: 10px;\n      font-size: 0.85rem;\n    }\n\n    .toggle-switch {\n      position: relative;\n      width: 50px;\n      height: 26px;\n    }\n\n    .toggle-switch input {\n      opacity: 0;\n      width: 0;\n      height: 0;\n    }\n\n    .slider {\n      position: absolute;\n      cursor: pointer;\n      top: 0;\n      left: 0;\n      right: 0;\n      bottom: 0;\n      background-color: #374151;\n      transition: .3s;\n      border-radius: 34px;\n    }\n\n    .slider:before {\n      position: absolute;\n      content: \"\";\n      height: 20px;\n      width: 20px;\n      left: 3px;\n      bottom: 3px;\n      background-color: white;\n      transition: .3s;\n      border-radius: 50%;\n    }\n\n    input:checked + .slider {\n      background-color: var(--color-primary);\n      box-shadow: 0 0 8px var(--color-primary-glow);\n    }\n\n    input:checked + .slider:before {\n      transform: translateX(24px);\n    }\n\n    .how-to-play {\n      margin-top: 10px;\n      background: rgba(0, 0, 0, 0.2);\n      border-radius: 16px;\n      padding: 16px;\n      border: 1px solid rgba(255, 255, 255, 0.03);\n    }\n\n    .how-to-play h3 {\n      font-size: 0.9rem;\n      margin-bottom: 8px;\n      color: var(--color-primary);\n      letter-spacing: 0.05em;\n      font-weight: 800;\n    }\n\n    .how-to-play p {\n      font-size: 0.8rem;\n      line-height: 1.5;\n      color: var(--color-text-muted);\n      margin-bottom: 6px;\n    }\n\n    .how-to-play p:last-child {\n      margin-bottom: 0;\n    }\n\n    .score-display {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 12px;\n      margin: 10px 0;\n    }\n\n    .score-block {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      background: rgba(255, 255, 255, 0.03);\n      border: 1px solid rgba(255, 255, 255, 0.05);\n      width: 100%;\n      padding: 20px;\n      border-radius: 20px;\n    }\n\n    .block-label {\n      font-size: 0.75rem;\n      letter-spacing: 0.1em;\n      font-weight: 600;\n      color: var(--color-text-muted);\n      margin-bottom: 4px;\n    }\n\n    .block-val {\n      font-size: 3.5rem;\n      font-weight: 800;\n      color: #fff;\n      line-height: 1;\n    }\n\n    .text-glow {\n      color: var(--color-secondary);\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      text-shadow: 0 0 10px rgba(59, 130, 246, 0.3);\n    }\n\n    #newBestBadge {\n      background: linear-gradient(90deg, #facc15 0%, #eab308 100%);\n      color: #000;\n      padding: 6px 16px;\n      border-radius: 12px;\n      font-weight: 800;\n      font-size: 0.8rem;\n      letter-spacing: 0.05em;\n      box-shadow: 0 4px 12px rgba(234, 179, 8, 0.35);\n      animation: pulse 1.5s infinite alternate;\n    }\n\n    #gameOverTitle {\n      font-family: var(--font-logo);\n      font-size: 2.75rem;\n      color: var(--color-danger);\n      text-shadow: 0 0 15px rgba(239, 68, 68, 0.3);\n    }\n\n    @keyframes pulse {\n      0% { transform: scale(1); }\n      100% { transform: scale(1.05); }\n    }\n\n    /* Dojo & Blades Custom Styles */\n    #dojoMenu {\n      max-width: 420px;\n    }\n    .dojo-tabs {\n      display: flex;\n      border-bottom: 1px solid var(--border-glass);\n      margin-bottom: 12px;\n      gap: 8px;\n    }\n    .dojo-tab-btn {\n      flex: 1;\n      padding: 10px;\n      background: none;\n      border: none;\n      color: var(--color-text-muted);\n      font-family: var(--font-ui);\n      font-weight: 600;\n      font-size: 0.95rem;\n      cursor: pointer;\n      border-bottom: 2px solid transparent;\n      transition: color 0.2s, border-color 0.2s;\n    }\n    .dojo-tab-btn.active {\n      color: var(--color-primary);\n      border-bottom-color: var(--color-primary);\n    }\n    .dojo-content-scroll {\n      max-height: 250px;\n      overflow-y: auto;\n      padding-right: 4px;\n      display: flex;\n      flex-direction: column;\n      gap: 12px;\n      text-align: left;\n    }\n    .dojo-content-scroll::-webkit-scrollbar {\n      width: 6px;\n    }\n    .dojo-content-scroll::-webkit-scrollbar-track {\n      background: rgba(255,255,255,0.02);\n      border-radius: 3px;\n    }\n    .dojo-content-scroll::-webkit-scrollbar-thumb {\n      background: rgba(255,255,255,0.15);\n      border-radius: 3px;\n    }\n    .blade-item {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      background: rgba(255, 255, 255, 0.03);\n      border: 1px solid rgba(255, 255, 255, 0.05);\n      border-radius: 16px;\n      padding: 10px 12px;\n      transition: background 0.2s, border-color 0.2s;\n    }\n    .blade-item.selected {\n      background: rgba(168, 85, 247, 0.08);\n      border-color: rgba(168, 85, 247, 0.3);\n    }\n    .blade-icon-preview {\n      width: 44px;\n      height: 44px;\n      border-radius: 12px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 1.5rem;\n      flex-shrink: 0;\n    }\n    .blade-details {\n      flex: 1;\n    }\n    .blade-name {\n      font-weight: 700;\n      font-size: 0.95rem;\n      color: #fff;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n    }\n    .blade-desc {\n      font-size: 0.75rem;\n      color: var(--color-text-muted);\n      margin-top: 2px;\n      line-height: 1.3;\n    }\n    .blade-unlock {\n      font-size: 0.7rem;\n      color: #fb7185;\n      font-weight: 600;\n      margin-top: 4px;\n    }\n    .blade-action-btn {\n      padding: 8px 12px;\n      border-radius: 10px;\n      font-size: 0.75rem;\n      font-weight: 600;\n      border: none;\n      cursor: pointer;\n      font-family: var(--font-ui);\n      transition: transform 0.1s;\n    }\n    .blade-action-btn:active {\n      transform: scale(0.95);\n    }\n    .blade-action-btn.equip {\n      background: var(--color-primary);\n      color: #fff;\n    }\n    .blade-action-btn.equipped {\n      background: rgba(255,255,255,0.1);\n      color: var(--color-text-muted);\n      cursor: default;\n    }\n    .blade-action-btn.locked {\n      background: rgba(0,0,0,0.25);\n      color: rgba(255,255,255,0.25);\n      cursor: not-allowed;\n    }\n    .stat-row {\n      display: flex;\n      justify-content: space-between;\n      border-bottom: 1px solid rgba(255,255,255,0.03);\n      padding: 8px 4px;\n      font-size: 0.85rem;\n    }\n    .stat-row:last-child {\n      border-bottom: none;\n    }\n    .stat-label {\n      color: var(--color-text-muted);\n    }\n    .stat-value {\n      font-weight: 700;\n      color: #fff;\n    }\n\n    @media (max-width: 360px) {\n      .menu-card {\n        padding: 24px 18px;\n        gap: 20px;\n      }\n      .logo-title {\n        font-size: 2.25rem;\n      }\n      .btn {\n        padding: 12px;\n      }\n    }\n  </style>\n</head>\n<body>\n  <canvas id=\"gameCanvas\"></canvas>\n\n  <div id=\"hud\" class=\"hidden\">\n    <div class=\"hud-top-left\">\n      <div id=\"scoreLabel\">SCORE</div>\n      <div id=\"scoreValue\">0</div>\n    </div>\n    \n    <div class=\"hud-top-center\">\n      <div id=\"timerContainer\" class=\"hidden\">\n        <div id=\"timerLabel\">TIME</div>\n        <div id=\"timerValue\">60</div>\n      </div>\n      <div id=\"comboAnnouncer\"></div>\n    </div>\n\n    <div class=\"hud-top-right\">\n      <div id=\"livesContainer\">\n        <span class=\"heart active\"></span>\n        <span class=\"heart active\"></span>\n        <span class=\"heart active\"></span>\n      </div>\n      <button id=\"pauseButton\" aria-label=\"Pause Game\">\n        <svg viewBox=\"0 0 24 24\"><path fill=\"currentColor\" d=\"M14,19H18V5H14M6,19H10V5H6V19Z\"/></svg>\n      </button>\n    </div>\n  </div>\n\n  <div id=\"overlayContainer\" class=\"overlay-container\">\n    \n    <div id=\"mainMenu\" class=\"menu-card active\">\n      <div class=\"logo-area\">\n        <span class=\"title-bg-glow\"></span>\n        <h1 class=\"logo-title\">NINJA<span class=\"highlight\">SLICE</span></h1>\n        <p class=\"logo-subtitle\">A Low-Key Slice Game</p>\n        <div class=\"high-score-banner\" style=\"margin-top: 10px; font-size: 0.85rem; font-weight: 600; opacity: 0.85;\">\n          <span>Best: </span><span id=\"bestScoreVal\" style=\"color: #facc15; font-weight: 800;\">0</span>\n        </div>\n      </div>\n\n      <div class=\"menu-actions\">\n        <button id=\"btnClassic\" class=\"btn btn-primary\">\n          <span class=\"btn-glow\"></span>\n          <span class=\"btn-text\">CLASSIC MODE</span>\n          <span class=\"btn-subtext\">3 Lives &amp; Bombs</span>\n        </button>\n        \n        <button id=\"btnArcade\" class=\"btn btn-primary\">\n          <span class=\"btn-glow\"></span>\n          <span class=\"btn-text\">ARCADE MODE</span>\n          <span class=\"btn-subtext\">60s Frenzy &amp; Combos</span>\n        </button>\n\n        <button id=\"btnZen\" class=\"btn btn-primary\">\n          <span class=\"btn-glow\"></span>\n          <span class=\"btn-text\">ZEN MODE</span>\n          <span class=\"btn-subtext\">Relaxed. No Bombs, No Lives</span>\n        </button>\n      </div>\n\n      <div class=\"menu-footer\" style=\"justify-content: space-around; gap: 32px;\">\n        <button id=\"btnSettings\" class=\"btn-icon-label\" aria-label=\"Settings\">\n          <svg viewBox=\"0 0 24 24\"><path fill=\"currentColor\" d=\"M12,15.5A3.5,3.5 0 0,1 8.5,12A3.5,3.5 0 0,1 12,8.5A3.5,3.5 0 0,1 15.5,12A3.5,3.5 0 0,1 12,15.5M19.43,12.97C19.47,12.65 19.5,12.33 19.5,12C19.5,11.67 19.47,11.34 19.43,11L21.54,9.37C21.73,9.22 21.78,8.95 21.66,8.73L19.66,5.27C19.54,5.05 19.27,4.96 19.05,5.05L16.56,6.05C16.04,5.66 15.47,5.34 14.86,5.08L14.47,2.42C14.43,2.18 14.22,2 13.97,2H9.97C9.72,2 9.51,2.18 9.47,2.42L9.08,5.08C8.47,5.34 7.9,5.66 7.38,6.05L4.89,5.05C4.67,4.96 4.4,5.05 4.28,5.27L2.28,8.73C2.16,8.95 2.21,9.22 2.4,9.37L4.51,11C4.47,11.34 4.45,11.67 4.45,12C4.45,12.33 4.47,12.65 4.51,12.97L2.4,14.63C2.21,14.78 2.16,15.05 2.28,15.27L4.28,18.73C4.4,18.95 4.67,19.04 4.89,18.95L7.38,17.95C7.9,18.34 8.47,18.66 9.08,18.92L9.47,21.58C9.51,21.82 9.72,22 9.97,22H13.97C14.22,22 14.43,21.82 14.47,21.58L14.86,18.92C15.47,18.66 16.04,18.34 16.56,17.95L19.05,18.95C19.27,19.04 19.54,18.95 19.66,18.73L21.66,15.27C21.78,15.05 21.73,14.78 21.54,14.63L19.43,12.97Z\"/></svg>\n          <span>Settings</span>\n        </button>\n        <button id=\"btnDojo\" class=\"btn-icon-label\" aria-label=\"Dojo &amp; Blades\">\n          <svg viewBox=\"0 0 24 24\"><path fill=\"currentColor\" d=\"M19.78 2.2C19.39 1.81 18.76 1.81 18.37 2.2L12.43 8.14L9.07 4.78C8.68 4.39 8.05 4.39 7.66 4.78L2.2 10.24C1.81 10.63 1.81 11.26 2.2 11.65L5.56 15.01L2.2 18.37C1.81 18.76 1.81 19.39 2.2 19.78C2.59 20.17 3.22 20.17 3.61 19.78L6.97 16.42L10.33 19.78C10.72 20.17 11.35 20.17 11.74 19.78L17.2 14.32C17.59 13.93 17.59 13.3 17.2 12.91L13.84 9.55L19.78 3.61C20.17 3.22 20.17 2.59 19.78 2.2M13.66 12.2L11.78 14.08L9.9 12.2L11.78 10.32L13.66 12.2M7.66 8.14L9.54 10.02L7.66 11.9L5.78 10.02L7.66 8.14Z\"/></svg>\n          <span>Dojo</span>\n        </button>\n      </div>\n    </div>\n\n    <div id=\"dojoMenu\" class=\"menu-card hidden\">\n      <h2>DOJO &amp; BLADES</h2>\n      \n      <div class=\"dojo-tabs\">\n        <button id=\"tabBlades\" class=\"dojo-tab-btn active\">BLADES</button>\n        <button id=\"tabStats\" class=\"dojo-tab-btn\">STATS</button>\n      </div>\n\n      <div id=\"dojoContentBlades\" class=\"dojo-content-scroll\">\n        <!-- Blade items dynamically rendered -->\n      </div>\n\n      <div id=\"dojoContentStats\" class=\"dojo-content-scroll hidden\">\n        <!-- Stats list -->\n      </div>\n\n      <div class=\"menu-actions\">\n        <button id=\"btnDojoBack\" class=\"btn btn-secondary\">BACK</button>\n      </div>\n    </div>\n\n    <div id=\"pauseMenu\" class=\"menu-card hidden\">\n      <h2>GAME PAUSED</h2>\n      <div class=\"menu-actions\">\n        <button id=\"btnResume\" class=\"btn btn-secondary\">RESUME</button>\n        <button id=\"btnRestartPause\" class=\"btn btn-secondary\">RESTART</button>\n        <button id=\"btnQuitPause\" class=\"btn btn-danger\">MAIN MENU</button>\n      </div>\n    </div>\n\n    <div id=\"settingsMenu\" class=\"menu-card hidden\">\n      <h2>SETTINGS</h2>\n      <div class=\"settings-content\">\n        <div class=\"settings-row\">\n          <label for=\"toggleSFX\">Sound Effects (SFX)</label>\n          <div class=\"toggle-switch\">\n            <input type=\"checkbox\" id=\"toggleSFX\" checked>\n            <span class=\"slider\"></span>\n          </div>\n        </div>\n        <div class=\"settings-row\">\n          <button id=\"btnResetScore\" class=\"btn btn-danger btn-sm\">Reset All High Scores</button>\n        </div>\n        <div class=\"how-to-play\">\n          <h3>How to Play</h3>\n          <p>👉 Swipe your finger (or drag mouse) across fruits to slice them.</p>\n          <p>💣 Avoid slicing the BOMBS! (In Classic &amp; Arcade)</p>\n          <p>🍎 Slice multiple fruits in one swipe for Combo multipliers!</p>\n          <p>❤️ Don't miss fruits in Classic mode, or you'll lose lives.</p>\n        </div>\n      </div>\n      <div class=\"menu-actions\">\n        <button id=\"btnSettingsBack\" class=\"btn btn-secondary\">BACK</button>\n      </div>\n    </div>\n\n    <div id=\"gameOverMenu\" class=\"menu-card hidden\">\n      <h2 id=\"gameOverTitle\">GAME OVER</h2>\n      <p id=\"gameOverMode\" class=\"text-glow\">Classic Mode</p>\n      \n      <div class=\"score-display\">\n        <div class=\"score-block\">\n          <span class=\"block-label\">FINAL SCORE</span>\n          <span id=\"finalScoreVal\" class=\"block-val\">0</span>\n        </div>\n        <div class=\"score-block hidden\" id=\"newBestBadge\">\n          <span class=\"badge-text\">NEW BEST!</span>\n        </div>\n      </div>\n\n      <div class=\"menu-actions\">\n        <button id=\"btnRestartOver\" class=\"btn btn-primary\">PLAY AGAIN</button>\n        <button id=\"btnQuitOver\" class=\"btn btn-secondary\">MAIN MENU</button>\n      </div>\n    </div>\n\n  </div>\n\n  <!-- Audio synthesizers class definition -->\n  <script>\n    class SoundController {\n      constructor() {\n        this.ctx = null;\n        this.enabled = true;\n        this.noiseBuffer = null;\n      }\n\n      init() {\n        if (this.ctx) return;\n        try {\n          const AudioCtx = window.AudioContext || window.webkitAudioContext;\n          this.ctx = new AudioCtx();\n          this.generateNoiseBuffer();\n        } catch (e) {\n          console.warn(\"Web Audio API is not supported:\", e);\n        }\n      }\n\n      resume() {\n        if (this.ctx && this.ctx.state === 'suspended') {\n          this.ctx.resume();\n        }\n      }\n\n      generateNoiseBuffer() {\n        if (!this.ctx) return;\n        const bufferSize = this.ctx.sampleRate * 0.4;\n        this.noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);\n        const data = this.noiseBuffer.getChannelData(0);\n        for (let i = 0; i < bufferSize; i++) {\n          data[i] = Math.random() * 2 - 1;\n        }\n      }\n\n      setEnabled(val) {\n        this.enabled = val;\n        if (val) {\n          this.init();\n          this.resume();\n        }\n      }\n\n      playSwoosh(bladeStyle = 'classic') {\n        if (!this.enabled || !this.ctx) return;\n        this.resume();\n        const now = this.ctx.currentTime;\n        \n        const noiseNode = this.ctx.createBufferSource();\n        noiseNode.buffer = this.noiseBuffer;\n\n        const noiseFilter = this.ctx.createBiquadFilter();\n        noiseFilter.type = 'bandpass';\n        noiseFilter.Q.value = 3;\n        \n        let startFreq = 1400;\n        let endFreq = 300;\n        let noiseVol = 0.35;\n        let swooshDuration = 0.18;\n        let oscType = 'triangle';\n        let oscStartFreq = 120;\n        let oscEndFreq = 50;\n        let oscVol = 0.12;\n\n        if (bladeStyle === 'FIRE') {\n          startFreq = 900;\n          endFreq = 200;\n          noiseVol = 0.45;\n          oscStartFreq = 90;\n          oscEndFreq = 30;\n          oscVol = 0.18;\n        } else if (bladeStyle === 'ICE') {\n          startFreq = 2200;\n          endFreq = 700;\n          noiseVol = 0.25;\n          oscStartFreq = 200;\n          oscEndFreq = 120;\n          oscType = 'sine';\n          oscVol = 0.08;\n        } else if (bladeStyle === 'RAINBOW') {\n          startFreq = 1600;\n          endFreq = 500;\n          oscStartFreq = 160;\n          oscEndFreq = 90;\n          oscVol = 0.15;\n        } else if (bladeStyle === 'SHADOW') {\n          startFreq = 600;\n          endFreq = 100;\n          noiseVol = 0.5;\n          oscStartFreq = 70;\n          oscEndFreq = 25;\n          oscVol = 0.25;\n        }\n\n        noiseFilter.frequency.setValueAtTime(startFreq, now);\n        noiseFilter.frequency.exponentialRampToValueAtTime(endFreq, now + swooshDuration);\n\n        const noiseGain = this.ctx.createGain();\n        noiseGain.gain.setValueAtTime(0.0, now);\n        noiseGain.gain.linearRampToValueAtTime(noiseVol, now + 0.04);\n        noiseGain.gain.exponentialRampToValueAtTime(0.01, now + swooshDuration);\n\n        noiseNode.connect(noiseFilter);\n        noiseFilter.connect(noiseGain);\n        noiseGain.connect(this.ctx.destination);\n        \n        noiseNode.start(now);\n        noiseNode.stop(now + swooshDuration + 0.02);\n\n        const osc = this.ctx.createOscillator();\n        const oscGain = this.ctx.createGain();\n        \n        osc.type = oscType;\n        osc.frequency.setValueAtTime(oscStartFreq, now);\n        osc.frequency.exponentialRampToValueAtTime(oscEndFreq, now + swooshDuration - 0.03);\n\n        oscGain.gain.setValueAtTime(oscVol, now);\n        oscGain.gain.exponentialRampToValueAtTime(0.01, now + swooshDuration - 0.03);\n\n        osc.connect(oscGain);\n        oscGain.connect(this.ctx.destination);\n\n        osc.start(now);\n        osc.stop(now + swooshDuration - 0.02);\n      }\n\n      playSplat(bladeStyle = 'classic') {\n        if (!this.enabled || !this.ctx) return;\n        this.resume();\n        const now = this.ctx.currentTime;\n\n        const noiseNode = this.ctx.createBufferSource();\n        noiseNode.buffer = this.noiseBuffer;\n\n        const noiseFilter = this.ctx.createBiquadFilter();\n        noiseFilter.type = 'bandpass';\n        noiseFilter.Q.value = 5;\n        \n        let startFreq = 2200;\n        let endFreq = 600;\n        let splatVol = 0.5;\n\n        if (bladeStyle === 'FIRE') {\n          startFreq = 1800;\n          endFreq = 400;\n          splatVol = 0.6;\n        } else if (bladeStyle === 'ICE') {\n          startFreq = 3500;\n          endFreq = 1200;\n          splatVol = 0.35;\n        } else if (bladeStyle === 'SHADOW') {\n          startFreq = 1000;\n          endFreq = 200;\n          splatVol = 0.7;\n        }\n\n        noiseFilter.frequency.setValueAtTime(startFreq, now);\n        noiseFilter.frequency.exponentialRampToValueAtTime(endFreq, now + 0.12);\n\n        const noiseGain = this.ctx.createGain();\n        noiseGain.gain.setValueAtTime(0.0, now);\n        noiseGain.gain.linearRampToValueAtTime(splatVol, now + 0.02);\n        noiseGain.gain.exponentialRampToValueAtTime(0.01, now + 0.15);\n\n        noiseNode.connect(noiseFilter);\n        noiseFilter.connect(noiseGain);\n        noiseGain.connect(this.ctx.destination);\n        \n        noiseNode.start(now);\n        noiseNode.stop(now + 0.18);\n\n        const osc = this.ctx.createOscillator();\n        const oscGain = this.ctx.createGain();\n\n        osc.type = bladeStyle === 'ICE' ? 'triangle' : 'sine';\n        let oscStart = 220;\n        let oscEnd = 60;\n\n        if (bladeStyle === 'FIRE') {\n          oscStart = 180;\n          oscEnd = 40;\n        } else if (bladeStyle === 'ICE') {\n          oscStart = 380;\n          oscEnd = 180;\n        } else if (bladeStyle === 'SHADOW') {\n          oscStart = 120;\n          oscEnd = 30;\n        }\n\n        osc.frequency.setValueAtTime(oscStart, now);\n        osc.frequency.exponentialRampToValueAtTime(oscEnd, now + 0.15);\n\n        oscGain.gain.setValueAtTime(0.35, now);\n        oscGain.gain.exponentialRampToValueAtTime(0.01, now + 0.15);\n\n        osc.connect(oscGain);\n        oscGain.connect(this.ctx.destination);\n\n        osc.start(now);\n        osc.stop(now + 0.16);\n\n        if (bladeStyle === 'FIRE') {\n          const fireOsc = this.ctx.createOscillator();\n          const fireGain = this.ctx.createGain();\n          fireOsc.type = 'sawtooth';\n          fireOsc.frequency.setValueAtTime(800, now);\n          fireOsc.frequency.linearRampToValueAtTime(100, now + 0.1);\n          fireGain.gain.setValueAtTime(0.08, now);\n          fireGain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);\n          fireOsc.connect(fireGain);\n          fireGain.connect(this.ctx.destination);\n          fireOsc.start(now);\n          fireOsc.stop(now + 0.1);\n        } else if (bladeStyle === 'ICE') {\n          const chimeOsc = this.ctx.createOscillator();\n          const chimeGain = this.ctx.createGain();\n          chimeOsc.type = 'sine';\n          chimeOsc.frequency.setValueAtTime(1200, now);\n          chimeOsc.frequency.linearRampToValueAtTime(2000, now + 0.08);\n          chimeGain.gain.setValueAtTime(0.12, now);\n          chimeGain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);\n          chimeOsc.connect(chimeGain);\n          chimeGain.connect(this.ctx.destination);\n          chimeOsc.start(now);\n          chimeOsc.stop(now + 0.08);\n        }\n      }\n\n      playCritical() {\n        if (!this.enabled || !this.ctx) return;\n        this.resume();\n        const now = this.ctx.currentTime;\n        \n        const osc1 = this.ctx.createOscillator();\n        const osc2 = this.ctx.createOscillator();\n        const gain = this.ctx.createGain();\n        \n        osc1.type = 'sine';\n        osc1.frequency.setValueAtTime(880, now);\n        osc1.frequency.exponentialRampToValueAtTime(1760, now + 0.35);\n        \n        osc2.type = 'triangle';\n        osc2.frequency.setValueAtTime(440, now);\n        osc2.frequency.exponentialRampToValueAtTime(1320, now + 0.35);\n\n        gain.gain.setValueAtTime(0.3, now);\n        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);\n        \n        osc1.connect(gain);\n        osc2.connect(gain);\n        gain.connect(this.ctx.destination);\n        \n        osc1.start(now);\n        osc2.start(now);\n        osc1.stop(now + 0.36);\n        osc2.stop(now + 0.36);\n      }\n\n      playExplosion() {\n        if (!this.enabled || !this.ctx) return;\n        this.resume();\n        const now = this.ctx.currentTime;\n\n        const osc = this.ctx.createOscillator();\n        const oscGain = this.ctx.createGain();\n        const oscFilter = this.ctx.createBiquadFilter();\n\n        osc.type = 'sawtooth';\n        osc.frequency.setValueAtTime(160, now);\n        osc.frequency.linearRampToValueAtTime(25, now + 0.8);\n\n        oscFilter.type = 'lowpass';\n        oscFilter.frequency.setValueAtTime(300, now);\n        oscFilter.frequency.exponentialRampToValueAtTime(40, now + 0.6);\n\n        oscGain.gain.setValueAtTime(0.65, now);\n        oscGain.gain.exponentialRampToValueAtTime(0.01, now + 0.95);\n\n        osc.connect(oscFilter);\n        oscFilter.connect(oscGain);\n        oscGain.connect(this.ctx.destination);\n\n        osc.start(now);\n        osc.stop(now + 1.0);\n\n        const noiseNode = this.ctx.createBufferSource();\n        noiseNode.buffer = this.noiseBuffer;\n\n        const noiseFilter = this.ctx.createBiquadFilter();\n        noiseFilter.type = 'lowpass';\n        noiseFilter.frequency.setValueAtTime(1800, now);\n        noiseFilter.frequency.exponentialRampToValueAtTime(100, now + 0.7);\n\n        const noiseGain = this.ctx.createGain();\n        noiseGain.gain.setValueAtTime(0.55, now);\n        noiseGain.gain.exponentialRampToValueAtTime(0.01, now + 0.8);\n\n        noiseNode.connect(noiseFilter);\n        noiseFilter.connect(noiseGain);\n        noiseGain.connect(this.ctx.destination);\n\n        noiseNode.start(now);\n        noiseNode.stop(now + 0.8);\n      }\n\n      playFuse() {\n        if (!this.enabled || !this.ctx) return null;\n        this.resume();\n        const now = this.ctx.currentTime;\n        \n        const noiseNode = this.ctx.createBufferSource();\n        noiseNode.buffer = this.noiseBuffer;\n        noiseNode.loop = true;\n\n        const filter = this.ctx.createBiquadFilter();\n        filter.type = 'highpass';\n        filter.frequency.setValueAtTime(4000, now);\n\n        const gain = this.ctx.createGain();\n        gain.gain.setValueAtTime(0.06, now);\n\n        noiseNode.connect(filter);\n        filter.connect(gain);\n        gain.connect(this.ctx.destination);\n\n        noiseNode.start(now);\n\n        return {\n          stop: () => {\n            try {\n              noiseNode.stop();\n            } catch(e) {}\n          }\n        };\n      }\n\n      playCombo(count) {\n        if (!this.enabled || !this.ctx) return;\n        this.resume();\n        const now = this.ctx.currentTime;\n        const scale = [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33];\n        const pitches = [];\n\n        const notesToPlay = Math.min(count, 6);\n        for (let i = 0; i < notesToPlay; i++) {\n          pitches.push(scale[i % scale.length]);\n        }\n\n        pitches.forEach((freq, idx) => {\n          const timeOffset = idx * 0.07;\n          const noteTime = now + timeOffset;\n\n          const osc = this.ctx.createOscillator();\n          const gainNode = this.ctx.createGain();\n\n          osc.type = 'triangle';\n          osc.frequency.setValueAtTime(freq, noteTime);\n\n          gainNode.gain.setValueAtTime(0.0, noteTime);\n          gainNode.gain.linearRampToValueAtTime(0.2, noteTime + 0.02);\n          gainNode.gain.exponentialRampToValueAtTime(0.001, noteTime + 0.35);\n\n          osc.connect(gainNode);\n          gainNode.connect(this.ctx.destination);\n\n          osc.start(noteTime);\n          osc.stop(noteTime + 0.4);\n        });\n      }\n\n      playBlitzSpawn() {\n        if (!this.enabled || !this.ctx) return;\n        this.resume();\n        const now = this.ctx.currentTime;\n        const osc = this.ctx.createOscillator();\n        const gainNode = this.ctx.createGain();\n\n        osc.type = 'sine';\n        osc.frequency.setValueAtTime(600, now);\n        osc.frequency.exponentialRampToValueAtTime(1200, now + 0.3);\n\n        gainNode.gain.setValueAtTime(0.0, now);\n        gainNode.gain.linearRampToValueAtTime(0.18, now + 0.05);\n        gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.35);\n\n        osc.connect(gainNode);\n        gainNode.connect(this.ctx.destination);\n\n        osc.start(now);\n        osc.stop(now + 0.4);\n      }\n    }\n\n    const gameAudio = new SoundController();\n  </script>\n\n  <!-- Core Game Engine Loop script -->\n  <script>\n    const GRAVITY = 0.28;\n    const MAX_FRUITS_ON_SCREEN = 8;\n    const MIN_LAUNCH_INTERVAL = 800;\n\n        const FRUIT_TYPES = {\n      WATERMELON: { name: 'Watermelon', radius: 45, color: '#ef4444' },\n      ORANGE:     { name: 'Orange',     radius: 36, color: '#f97316' },\n      APPLE:      { name: 'Apple',      radius: 34, color: '#eab308' },\n      BANANA:     { name: 'Banana',     radius: 32, color: '#fef08a' },\n      COCONUT:    { name: 'Coconut',    radius: 38, color: '#ffffff' },\n      PINEAPPLE:  { name: 'Pineapple',  radius: 42, color: '#fbbf24' },\n      PEACH:      { name: 'Peach',      radius: 35, color: '#fbcfe8' },\n      KIWI:       { name: 'Kiwi',       radius: 31, color: '#a3e635' }\n    };\n\n    const BLITZ_TYPES = {\n      FREEZE: { name: 'Freeze', radius: 36, color: '#06b6d4', effect: 'freeze' },\n      FRENZY: { name: 'Frenzy', radius: 36, color: '#ec4899', effect: 'frenzy' },\n      DOUBLE: { name: 'Double', radius: 36, color: '#a855f7', effect: 'double' }\n    };\n\n    const BLADES = {\n      CLASSIC: {\n        id: 'CLASSIC',\n        name: 'Classic Blade',\n        desc: 'The original ninja slash. Simple and precise.',\n        icon: '⚔️',\n        color: '#ffffff',\n        shadowColor: '#a855f7',\n        particleType: 'classic',\n        unlockDesc: 'Default blade'\n      },\n      FIRE: {\n        id: 'FIRE',\n        name: 'Fire Blade',\n        desc: 'Ignite the dojo. Slashes leave rising fire embers.',\n        icon: '🔥',\n        color: '#f97316',\n        shadowColor: '#ef4444',\n        particleType: 'fire',\n        unlockDesc: 'Slice 100 fruits total'\n      },\n      ICE: {\n        id: 'ICE',\n        name: 'Ice Blade',\n        desc: 'Frostbite slash. Sparkles down snow-white frost.',\n        icon: '❄️',\n        color: '#e0f2fe',\n        shadowColor: '#06b6d4',\n        particleType: 'ice',\n        unlockDesc: 'Score 150+ in Zen mode'\n      },\n      RAINBOW: {\n        id: 'RAINBOW',\n        name: 'Rainbow Blade',\n        desc: 'Taste the rainbow. Color-shifting trail with confetti.',\n        icon: '🌈',\n        color: 'rainbow',\n        shadowColor: 'rainbow',\n        particleType: 'rainbow',\n        unlockDesc: 'Get a 5-fruit combo'\n      },\n      SHADOW: {\n        id: 'SHADOW',\n        name: 'Shadow Blade',\n        desc: 'Slice through dimensions. Leaves a trail of dark void smoke.',\n        icon: '🌌',\n        color: '#1e1b4b',\n        shadowColor: '#4c1d95',\n        particleType: 'shadow',\n        unlockDesc: 'Score 80+ in Arcade with 0 bombs hit'\n      }\n    };\n\n    function getDistPointToSegment(px, py, x1, y1, x2, y2) {\n      const dx = x2 - x1;\n      const dy = y2 - y1;\n      const lenSq = dx * dx + dy * dy;\n      \n      if (lenSq === 0) {\n        const dX = px - x1;\n        const dY = py - y1;\n        return Math.sqrt(dX * dX + dY * dY);\n      }\n      \n      let t = ((px - x1) * dx + (py - y1) * dy) / lenSq;\n      t = Math.max(0, Math.min(1, t));\n      \n      const qx = x1 + t * dx;\n      const qy = y1 + t * dy;\n      const diffX = px - qx;\n      const diffY = py - qy;\n      return Math.sqrt(diffX * diffX + diffY * diffY);\n    }\n\n    class JuiceSplatter {\n      constructor(x, y, color) {\n        this.x = x;\n        this.y = y;\n        this.color = color;\n        this.radius = 20 + Math.random() * 25;\n        this.alpha = 0.55;\n        this.decay = 0.0015 + Math.random() * 0.002;\n        this.droplets = [];\n        \n        const dropletCount = 3 + Math.floor(Math.random() * 5);\n        for (let i = 0; i < dropletCount; i++) {\n          const angle = Math.random() * Math.PI * 2;\n          const dist = this.radius * (0.5 + Math.random() * 0.8);\n          const canDrip = Math.random() < 0.45;\n          this.droplets.push({\n            dx: Math.cos(angle) * dist,\n            dy: Math.sin(angle) * dist,\n            r: 2.5 + Math.random() * 5,\n            dripY: 0,\n            dripSpeed: canDrip ? 0.15 + Math.random() * 0.3 : 0\n          });\n        }\n      }\n\n      update(dt) {\n        this.alpha -= this.decay * dt;\n        this.droplets.forEach(d => {\n          if (d.dripSpeed > 0) {\n            d.dripY += d.dripSpeed * dt;\n          }\n        });\n        return this.alpha > 0;\n      }\n\n      draw(ctx) {\n        ctx.save();\n        ctx.globalAlpha = this.alpha;\n        ctx.fillStyle = this.color;\n        \n        ctx.beginPath();\n        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);\n        ctx.fill();\n        \n        this.droplets.forEach(d => {\n          if (d.dripSpeed > 0) {\n            ctx.beginPath();\n            ctx.arc(this.x + d.dx, this.y + d.dy + d.dripY, d.r, 0, Math.PI * 2);\n            ctx.fill();\n            \n            ctx.beginPath();\n            ctx.rect(this.x + d.dx - d.r * 0.5, this.y + d.dy, d.r, d.dripY);\n            ctx.fill();\n          } else {\n            ctx.beginPath();\n            ctx.arc(this.x + d.dx, this.y + d.dy, d.r, 0, Math.PI * 2);\n            ctx.fill();\n          }\n        });\n        \n        ctx.restore();\n      }\n    }\n\n    class PhysicsParticle {\n      constructor(x, y, vx, vy, color, size, type = 'juice', bladeStyle = 'classic') {\n        this.x = x;\n        this.y = y;\n        this.vx = vx;\n        this.vy = vy;\n        this.color = color;\n        this.size = size;\n        this.alpha = 1.0;\n        this.decay = type === 'fuse' ? 0.08 : 0.025;\n        this.type = type;\n        this.bladeStyle = bladeStyle;\n        \n        if (type === 'blade') {\n          if (bladeStyle === 'FIRE') {\n            this.decay = 0.045;\n          } else if (bladeStyle === 'ICE') {\n            this.decay = 0.035;\n          } else if (bladeStyle === 'RAINBOW') {\n            this.decay = 0.04;\n          } else if (bladeStyle === 'SHADOW') {\n            this.decay = 0.02;\n          }\n        }\n      }\n\n      update(dt) {\n        this.x += this.vx * dt;\n        this.y += this.vy * dt;\n        \n        if (this.type === 'juice') {\n          this.vy += GRAVITY * 0.7 * dt;\n          this.vx *= Math.pow(0.97, dt);\n        } else if (this.type === 'fuse') {\n          this.vx *= Math.pow(0.95, dt);\n          this.vy *= Math.pow(0.95, dt);\n        } else if (this.type === 'blade') {\n          this.vx *= Math.pow(0.9, dt);\n          this.vy *= Math.pow(0.9, dt);\n          \n          if (this.bladeStyle === 'FIRE') {\n            this.vy -= 0.12 * dt;\n            this.vx += (Math.random() - 0.5) * 0.2 * dt;\n          } else if (this.bladeStyle === 'ICE') {\n            this.vy += 0.04 * dt;\n            this.vx += Math.sin(this.y * 0.05) * 0.08 * dt;\n          } else if (this.bladeStyle === 'RAINBOW') {\n            this.vy += (Math.random() - 0.5) * 0.1 * dt;\n            this.vx += (Math.random() - 0.5) * 0.1 * dt;\n          } else if (this.bladeStyle === 'SHADOW') {\n            this.size += 0.22 * dt;\n            this.vx *= Math.pow(0.85, dt);\n            this.vy *= Math.pow(0.85, dt);\n          }\n        }\n        \n        this.alpha -= this.decay * dt;\n        return this.alpha > 0;\n      }\n\n      draw(ctx) {\n        ctx.save();\n        ctx.globalAlpha = this.alpha;\n        ctx.fillStyle = this.color;\n        \n        if (this.type === 'blade') {\n          ctx.shadowBlur = this.bladeStyle === 'SHADOW' ? 6 : 12;\n          ctx.shadowColor = this.color;\n        }\n        \n        ctx.beginPath();\n        ctx.arc(this.x, this.y, Math.max(0.1, this.size), 0, Math.PI * 2);\n        ctx.fill();\n        ctx.restore();\n      }\n    }\n\n    class SlicedHalf {\n      constructor(x, y, vx, vy, sliceAngle, spin, radius, type, isBlitz = false) {\n        this.x = x;\n        this.y = y;\n        this.vx = vx;\n        this.vy = vy;\n        this.sliceAngle = sliceAngle;\n        this.spin = spin;\n        this.spinSpeed = 0.05 + Math.random() * 0.1;\n        this.radius = radius;\n        this.type = type;\n        this.isBlitz = isBlitz;\n        this.side = Math.random() < 0.5 ? 'left' : 'right';\n      }\n\n      update(dt) {\n        this.x += this.vx * dt;\n        this.y += this.vy * dt;\n        this.vy += GRAVITY * dt;\n        this.spin += this.spinSpeed * dt;\n        return this.y < window.innerHeight + 100;\n      }\n\n      draw(ctx) {\n        ctx.save();\n        ctx.translate(this.x, this.y);\n        ctx.rotate(this.sliceAngle + this.spin);\n        \n        ctx.beginPath();\n        if (this.side === 'left') {\n          ctx.rect(-this.radius * 3, -this.radius * 3, this.radius * 3, this.radius * 6);\n        } else {\n          ctx.rect(0, -this.radius * 3, this.radius * 3, this.radius * 6);\n        }\n        ctx.clip();\n        \n        if (this.isBlitz) {\n          drawBlitzGraphics(ctx, this.radius, this.type);\n        } else {\n          drawFruitGraphics(ctx, this.radius, this.type);\n        }\n        \n        ctx.restore();\n      }\n    }\n\n    class Fruit {\n      constructor(x, y, vx, vy, type, isBlitz = false) {\n        this.x = x;\n        this.y = y;\n        this.vx = vx;\n        this.vy = vy;\n        this.isBlitz = isBlitz;\n        this.type = type;\n        \n        const info = isBlitz ? BLITZ_TYPES[type] : FRUIT_TYPES[type];\n        this.radius = info.radius;\n        this.color = info.color;\n        \n        this.spin = Math.random() * Math.PI * 2;\n        this.spinSpeed = (Math.random() - 0.5) * 0.07;\n        this.sliced = false;\n      }\n\n      update(dt) {\n        this.x += this.vx * dt;\n        this.y += this.vy * dt;\n        this.vy += GRAVITY * dt;\n        this.spin += this.spinSpeed * dt;\n        return this.y < window.innerHeight + 100;\n      }\n\n      draw(ctx) {\n        ctx.save();\n        ctx.translate(this.x, this.y);\n        ctx.rotate(this.spin);\n        \n        if (this.isBlitz) {\n          drawBlitzGraphics(ctx, this.radius, this.type);\n        } else {\n          drawFruitGraphics(ctx, this.radius, this.type);\n        }\n        \n        ctx.restore();\n      }\n    }\n\n    class Bomb {\n      constructor(x, y, vx, vy) {\n        this.x = x;\n        this.y = y;\n        this.vx = vx;\n        this.vy = vy;\n        this.radius = 36;\n        this.spin = Math.random() * Math.PI * 2;\n        this.spinSpeed = 0.04;\n        this.sliced = false;\n        this.fuseSound = null;\n      }\n\n      startFuseSound() {\n        if (!this.fuseSound) {\n          this.fuseSound = gameAudio.playFuse();\n        }\n      }\n\n      stopFuseSound() {\n        if (this.fuseSound) {\n          this.fuseSound.stop();\n          this.fuseSound = null;\n        }\n      }\n\n      update(dt, particles) {\n        this.x += this.vx * dt;\n        this.y += this.vy * dt;\n        this.vy += GRAVITY * dt;\n        this.spin += this.spinSpeed * dt;\n        \n        const fuseLength = this.radius + 15;\n        const fuseAngle = this.spin - Math.PI / 2 + 0.3;\n        const sparkX = this.x + Math.cos(fuseAngle) * fuseLength;\n        const sparkY = this.y + Math.sin(fuseAngle) * fuseLength;\n        \n        if (Math.random() < 0.65) {\n          particles.push(new PhysicsParticle(\n            sparkX, sparkY, \n            (Math.random() - 0.5) * 3, \n            (Math.random() - 0.5) * 3 - 2, \n            Math.random() < 0.5 ? '#facc15' : '#ef4444', \n            2 + Math.random() * 3,\n            'fuse'\n          ));\n        }\n        \n        return this.y < window.innerHeight + 100;\n      }\n\n      draw(ctx) {\n        ctx.save();\n        ctx.translate(this.x, this.y);\n        ctx.rotate(this.spin);\n        \n        const grad = ctx.createRadialGradient(-this.radius * 0.3, -this.radius * 0.3, 2, 0, 0, this.radius);\n        grad.addColorStop(0, '#52525b');\n        grad.addColorStop(0.8, '#1e1b4b');\n        grad.addColorStop(1, '#090d16');\n        ctx.fillStyle = grad;\n        \n        ctx.beginPath();\n        ctx.arc(0, 0, this.radius, 0, Math.PI * 2);\n        ctx.fill();\n        \n        ctx.strokeStyle = 'rgba(239, 68, 68, 0.4)';\n        ctx.lineWidth = 1.5;\n        ctx.beginPath();\n        ctx.arc(0, 0, this.radius - 4, 0, Math.PI * 2);\n        ctx.stroke();\n\n        ctx.fillStyle = '#ef4444';\n        ctx.beginPath();\n        ctx.arc(0, 0, this.radius * 0.35, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.fillStyle = '#ffffff';\n        ctx.font = '800 12px ' + getComputedStyle(document.body).getPropertyValue('--font-ui');\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n        ctx.fillText('X', 0, 0);\n        \n        ctx.fillStyle = '#71717a';\n        ctx.fillRect(-6, -this.radius - 3, 12, 6);\n        \n        ctx.beginPath();\n        ctx.moveTo(0, -this.radius - 3);\n        ctx.quadraticCurveTo(15, -this.radius - 12, 10, -this.radius - 20);\n        ctx.strokeStyle = '#b45309';\n        ctx.lineWidth = 3;\n        ctx.stroke();\n        \n        ctx.restore();\n      }\n    }\n\n    function drawFruitGraphics(ctx, r, type) {\n      switch (type) {\n        case 'WATERMELON':\n          ctx.beginPath();\n          ctx.arc(0, 0, r, 0, Math.PI * 2);\n          ctx.fillStyle = '#16a34a';\n          ctx.fill();\n          \n          ctx.beginPath();\n          ctx.arc(0, 0, r - 5, 0, Math.PI * 2);\n          ctx.fillStyle = '#fef08a';\n          ctx.fill();\n          \n          ctx.beginPath();\n          ctx.arc(0, 0, r - 8, 0, Math.PI * 2);\n          ctx.fillStyle = '#dc2626';\n          ctx.fill();\n          \n          ctx.fillStyle = '#171717';\n          const seeds = [\n            {x:-12, y:-12}, {x:12, y:-12}, {x:-18, y:6}, {x:18, y:6}, {x:0, y:-18}, {x:0, y:12}\n          ];\n          seeds.forEach(s => {\n            ctx.beginPath();\n            ctx.ellipse(s.x, s.y, 2.5, 4, Math.PI / 4, 0, Math.PI * 2);\n            ctx.fill();\n          });\n          break;\n\n        case 'ORANGE':\n          ctx.beginPath();\n          ctx.arc(0, 0, r, 0, Math.PI * 2);\n          ctx.fillStyle = '#ea580c';\n          ctx.fill();\n          \n          ctx.beginPath();\n          ctx.arc(0, 0, r - 4, 0, Math.PI * 2);\n          ctx.fillStyle = '#ffedd5';\n          ctx.fill();\n          \n          ctx.fillStyle = '#f97316';\n          for (let i = 0; i < 8; i++) {\n            ctx.beginPath();\n            ctx.moveTo(0, 0);\n            ctx.arc(0, 0, r - 5, (i * Math.PI / 4) + 0.08, ((i + 1) * Math.PI / 4) - 0.08);\n            ctx.closePath();\n            ctx.fill();\n          }\n          break;\n\n        case 'APPLE':\n          ctx.beginPath();\n          ctx.arc(-r * 0.25, -r * 0.1, r * 0.75, 0, Math.PI * 2);\n          ctx.arc(r * 0.25, -r * 0.1, r * 0.75, 0, Math.PI * 2);\n          ctx.fillStyle = '#e11d48';\n          ctx.fill();\n          \n          ctx.beginPath();\n          ctx.arc(-r * 0.25, -r * 0.1, r * 0.65, 0, Math.PI * 2);\n          ctx.arc(r * 0.25, -r * 0.1, r * 0.65, 0, Math.PI * 2);\n          ctx.fillStyle = '#fef9c3';\n          ctx.fill();\n\n          ctx.fillStyle = '#78350f';\n          ctx.beginPath();\n          ctx.ellipse(-4, 0, 1.5, 3, -Math.PI / 6, 0, Math.PI * 2);\n          ctx.ellipse(4, 0, 1.5, 3, Math.PI / 6, 0, Math.PI * 2);\n          ctx.fill();\n\n          ctx.beginPath();\n          ctx.moveTo(0, -r * 0.6);\n          ctx.quadraticCurveTo(r * 0.3, -r * 1.1, r * 0.4, -r * 1.0);\n          ctx.lineWidth = 3;\n          ctx.strokeStyle = '#451a03';\n          ctx.stroke();\n\n          ctx.beginPath();\n          ctx.ellipse(r * 0.35, -r * 1.0, 3, 7, Math.PI / 3, 0, Math.PI * 2);\n          ctx.fillStyle = '#22c55e';\n          ctx.fill();\n          break;\n\n        case 'COCONUT':\n          ctx.beginPath();\n          ctx.arc(0, 0, r, 0, Math.PI * 2);\n          ctx.fillStyle = '#451a03';\n          ctx.fill();\n          \n          ctx.beginPath();\n          ctx.arc(0, 0, r - 5, 0, Math.PI * 2);\n          ctx.fillStyle = '#ffffff';\n          ctx.fill();\n          \n          ctx.beginPath();\n          ctx.arc(0, 0, r - 15, 0, Math.PI * 2);\n          ctx.fillStyle = '#f8fafc';\n          ctx.fill();\n          break;\n\n        case 'BANANA':\n          ctx.beginPath();\n          ctx.moveTo(-r * 0.9, -r * 0.3);\n          ctx.quadraticCurveTo(0, r * 0.9, r * 0.9, -r * 0.3);\n          ctx.quadraticCurveTo(0, r * 0.4, -r * 0.9, -r * 0.3);\n          ctx.closePath();\n          ctx.fillStyle = '#facc15';\n          ctx.fill();\n          \n          ctx.beginPath();\n          ctx.moveTo(-r * 0.8, -r * 0.2);\n          ctx.quadraticCurveTo(0, r * 0.7, r * 0.8, -r * 0.2);\n          ctx.strokeStyle = '#fef08a';\n          ctx.lineWidth = 2;\n          ctx.stroke();\n\n          ctx.fillStyle = '#3f220f';\n          ctx.beginPath();\n          ctx.arc(-r * 0.9, -r * 0.3, 3.5, 0, Math.PI * 2);\n          ctx.arc(r * 0.9, -r * 0.3, 3, 0, Math.PI * 2);\n          ctx.fill();\n          break;\n\n        case 'PINEAPPLE':\n          ctx.beginPath();\n          ctx.ellipse(0, 5, r * 0.75, r, 0, 0, Math.PI * 2);\n          ctx.fillStyle = '#d97706';\n          ctx.fill();\n\n          ctx.save();\n          ctx.beginPath();\n          ctx.ellipse(0, 5, r * 0.75, r, 0, 0, Math.PI * 2);\n          ctx.clip();\n          ctx.strokeStyle = '#f59e0b';\n          ctx.lineWidth = 1.5;\n          ctx.beginPath();\n          for (let x = -r; x < r; x += 10) {\n            ctx.moveTo(x - r, -r);\n            ctx.lineTo(x + r, r * 2);\n            ctx.moveTo(x + r, -r);\n            ctx.lineTo(x - r, r * 2);\n          }\n          ctx.stroke();\n          ctx.restore();\n\n          ctx.fillStyle = '#16a34a';\n          for (let i = -2; i <= 2; i++) {\n            ctx.beginPath();\n            ctx.moveTo(i * 6, -r * 0.85);\n            ctx.lineTo(i * 13, -r * 1.55);\n            ctx.lineTo(i * 6 + 6, -r * 0.85);\n            ctx.closePath();\n            ctx.fill();\n          }\n          break;\n\n        case 'PEACH':\n          ctx.beginPath();\n          ctx.arc(-r * 0.15, 0, r * 0.85, 0, Math.PI * 2);\n          ctx.arc(r * 0.15, 0, r * 0.85, 0, Math.PI * 2);\n          ctx.fillStyle = '#f43f5e';\n          ctx.fill();\n\n          ctx.beginPath();\n          ctx.arc(-r * 0.15, 0, r * 0.78, 0, Math.PI * 2);\n          ctx.arc(r * 0.15, 0, r * 0.78, 0, Math.PI * 2);\n          ctx.fillStyle = '#fbcfe8';\n          ctx.fill();\n\n          ctx.strokeStyle = 'rgba(225, 29, 72, 0.35)';\n          ctx.lineWidth = 2;\n          ctx.beginPath();\n          ctx.moveTo(0, -r * 0.7);\n          ctx.quadraticCurveTo(-r * 0.1, 0, 0, r * 0.7);\n          ctx.stroke();\n\n          ctx.fillStyle = '#92400e';\n          ctx.beginPath();\n          ctx.ellipse(0, 0, 3.5, 6, 0, 0, Math.PI * 2);\n          ctx.fill();\n          break;\n\n        case 'KIWI':\n          ctx.beginPath();\n          ctx.arc(0, 0, r, 0, Math.PI * 2);\n          ctx.fillStyle = '#78350f';\n          ctx.fill();\n\n          ctx.beginPath();\n          ctx.arc(0, 0, r - 3, 0, Math.PI * 2);\n          ctx.fillStyle = '#84cc16';\n          ctx.fill();\n\n          ctx.beginPath();\n          ctx.arc(0, 0, r * 0.32, 0, Math.PI * 2);\n          ctx.fillStyle = '#ecfccb';\n          ctx.fill();\n\n          ctx.fillStyle = '#171717';\n          const seedCount = 10;\n          for (let i = 0; i < seedCount; i++) {\n            const angle = (i * Math.PI * 2) / seedCount;\n            const dist = r * 0.54;\n            const sx = Math.cos(angle) * dist;\n            const sy = Math.sin(angle) * dist;\n            ctx.beginPath();\n            ctx.arc(sx, sy, 1.2, 0, Math.PI * 2);\n            ctx.fill();\n          }\n          break;\n      }\n    }\n\n    function drawBlitzGraphics(ctx, r, type) {\n      ctx.save();\n      ctx.shadowBlur = 15;\n      ctx.shadowColor = BLITZ_TYPES[type].color;\n      \n      ctx.strokeStyle = BLITZ_TYPES[type].color;\n      ctx.lineWidth = 3;\n      ctx.beginPath();\n      ctx.arc(0, 0, r, 0, Math.PI * 2);\n      ctx.stroke();\n      \n      ctx.fillStyle = 'rgba(255, 255, 255, 0.95)';\n      ctx.beginPath();\n      ctx.arc(0, 0, r - 5, 0, Math.PI * 2);\n      ctx.fill();\n      \n      ctx.fillStyle = BLITZ_TYPES[type].color;\n      ctx.textAlign = 'center';\n      ctx.textBaseline = 'middle';\n      \n      if (type === 'FREEZE') {\n        ctx.font = '24px Arial';\n        ctx.fillText('❄', 0, 0);\n      } else if (type === 'FRENZY') {\n        ctx.font = '800 24px Arial';\n        ctx.fillText('⚡', 0, 0);\n      } else if (type === 'DOUBLE') {\n        ctx.font = '800 18px ' + getComputedStyle(document.body).getPropertyValue('--font-ui');\n        ctx.fillText('2X', 0, 0);\n      }\n      \n      ctx.restore();\n    }\n\n    class SwipeTracker {\n      constructor() {\n        this.points = [];\n        this.active = false;\n        this.color = '#ffffff';\n        this.shadowColor = '#c084fc';\n        this.bladeStyle = 'CLASSIC';\n      }\n\n      start(x, y, bladeStyle = 'CLASSIC') {\n        this.active = true;\n        this.bladeStyle = bladeStyle;\n        this.points = [{ x, y, time: Date.now() }];\n        \n        const config = BLADES[bladeStyle] || BLADES.CLASSIC;\n        this.color = config.color;\n        this.shadowColor = config.shadowColor;\n        \n        gameAudio.playSwoosh(bladeStyle);\n      }\n\n      move(x, y, particles, bladeStyle = 'CLASSIC') {\n        if (!this.active) return;\n        const now = Date.now();\n        this.bladeStyle = bladeStyle;\n        \n        const config = BLADES[bladeStyle] || BLADES.CLASSIC;\n        this.color = config.color;\n        this.shadowColor = config.shadowColor;\n        \n        if (this.points.length > 0) {\n          const last = this.points[this.points.length - 1];\n          const vx = (x - last.x) * 0.1;\n          const vy = (y - last.y) * 0.1;\n          \n          if (Math.random() < 0.4) {\n            let sparkCol = this.color;\n            if (sparkCol === 'rainbow') {\n              const hue = (Date.now() / 3) % 360;\n              sparkCol = `hsl(${hue}, 100%, 65%)`;\n            }\n            particles.push(new PhysicsParticle(\n              x, y, \n              vx + (Math.random() - 0.5) * 2, \n              vy + (Math.random() - 0.5) * 2, \n              sparkCol, \n              1 + Math.random() * 3, \n              'blade',\n              bladeStyle\n            ));\n          }\n        }\n        \n        this.points.push({ x, y, time: now });\n      }\n\n      end() {\n        this.active = false;\n      }\n\n      update() {\n        const now = Date.now();\n        this.points = this.points.filter(p => now - p.time < 130);\n      }\n\n      draw(ctx) {\n        if (this.points.length < 2) return;\n        \n        ctx.save();\n        \n        const isRainbow = this.bladeStyle === 'RAINBOW';\n        \n        for (let i = 1; i < this.points.length; i++) {\n          const p1 = this.points[i - 1];\n          const p2 = this.points[i];\n          const progress = i / this.points.length;\n          \n          let strokeCol = this.color;\n          let shadowCol = this.shadowColor;\n          \n          if (isRainbow) {\n            const hue = (Date.now() / 3 + i * 12) % 360;\n            strokeCol = `hsl(${hue}, 100%, 75%)`;\n            shadowCol = `hsl(${hue}, 100%, 50%)`;\n          }\n          \n          ctx.shadowBlur = 14;\n          ctx.shadowColor = shadowCol;\n          \n          ctx.beginPath();\n          ctx.moveTo(p1.x, p1.y);\n          ctx.lineTo(p2.x, p2.y);\n          ctx.strokeStyle = strokeCol;\n          ctx.lineWidth = 9 * progress;\n          ctx.lineCap = 'round';\n          ctx.lineJoin = 'round';\n          ctx.stroke();\n        }\n        \n        ctx.restore();\n      }\n    }\n\n    class NinjaSliceGame {\n      constructor() {\n        this.canvas = document.getElementById('gameCanvas');\n        this.ctx = this.canvas.getContext('2d');\n        \n        this.gameState = 'MENU';\n        this.gameMode = 'CLASSIC';\n        \n        this.score = 0;\n        this.lives = 3;\n        this.timer = 0;\n        \n        this.fruits = [];\n        this.slicedHalves = [];\n        this.bombs = [];\n        this.particles = [];\n        this.splatters = [];\n        this.woodCuts = [];\n        this.screenShake = 0;\n        \n        this.swipe = new SwipeTracker();\n        this.lastLaunchTime = 0;\n        this.launchInterval = MIN_LAUNCH_INTERVAL;\n        this.timeElapsed = 0;\n        \n        this.blitzFreeze = 0;\n        this.blitzFrenzy = 0;\n        this.blitzDouble = 0;\n        this.frenzySpawnTimer = 0;\n        \n        this.comboCount = 0;\n        this.lastSliceTime = 0;\n        this.currentComboFruits = [];\n        \n        this.bombsHitThisGame = 0;\n        this.stats = {\n          totalSliced: 0,\n          totalCombos: 0,\n          maxCombo: 0,\n          totalBombsHit: 0,\n          gamesPlayed: 0\n        };\n        this.unlockedBlades = ['CLASSIC'];\n        this.selectedBlade = 'CLASSIC';\n        \n        this.bestScores = {\n          CLASSIC: 0,\n          ZEN: 0,\n          ARCADE: 0\n        };\n        \n        this.loadHighScores();\n        this.setupUIHandlers();\n        this.resize();\n        window.addEventListener('resize', () => this.resize());\n        this.setupInputHandlers();\n        \n        this.lastTime = performance.now();\n        requestAnimationFrame((t) => this.loop(t));\n      }\n\n      resize() {\n        this.dpr = window.devicePixelRatio || 1;\n        this.width = window.innerWidth;\n        this.height = window.innerHeight;\n        this.canvas.width = this.width * this.dpr;\n        this.canvas.height = this.height * this.dpr;\n        this.ctx.scale(this.dpr, this.dpr);\n      }\n\n      loadHighScores() {\n        try {\n          this.bestScores.CLASSIC = parseInt(localStorage.getItem('ninja_slice_best_CLASSIC')) || 0;\n          this.bestScores.ZEN = parseInt(localStorage.getItem('ninja_slice_best_ZEN')) || 0;\n          this.bestScores.ARCADE = parseInt(localStorage.getItem('ninja_slice_best_ARCADE')) || 0;\n          this.updateBestScoreDisplay();\n\n          const savedStats = localStorage.getItem('ninja_slice_stats');\n          if (savedStats) {\n            this.stats = Object.assign(this.stats, JSON.parse(savedStats));\n          }\n          \n          const savedUnlocked = localStorage.getItem('ninja_slice_unlocked');\n          if (savedUnlocked) {\n            this.unlockedBlades = JSON.parse(savedUnlocked);\n          }\n          if (!this.unlockedBlades.includes('CLASSIC')) {\n            this.unlockedBlades.push('CLASSIC');\n          }\n\n          const activeBlade = localStorage.getItem('ninja_slice_active_blade');\n          if (activeBlade && Object.keys(BLADES).includes(activeBlade)) {\n            this.selectedBlade = activeBlade;\n          }\n        } catch(e) {\n          console.warn(\"Storage restricted:\", e);\n        }\n      }\n\n      saveHighScore(mode, val) {\n        if (val > this.bestScores[mode]) {\n          this.bestScores[mode] = val;\n          try {\n            localStorage.setItem('ninja_slice_best_' + mode, val);\n          } catch(e) {}\n          this.updateBestScoreDisplay();\n          return true;\n        }\n        return false;\n      }\n\n      updateBestScoreDisplay() {\n        const currentModeBest = this.bestScores[this.gameMode];\n        document.getElementById('bestScoreVal').innerText = currentModeBest;\n      }\n\n      setupUIHandlers() {\n        document.getElementById('btnClassic').addEventListener('click', () => this.startGame('CLASSIC'));\n        document.getElementById('btnZen').addEventListener('click', () => this.startGame('ZEN'));\n        document.getElementById('btnArcade').addEventListener('click', () => this.startGame('ARCADE'));\n        \n        document.getElementById('btnSettings').addEventListener('click', () => this.showScreen('settingsMenu'));\n        document.getElementById('btnSettingsBack').addEventListener('click', () => this.showScreen('mainMenu'));\n        \n        document.getElementById('btnDojo').addEventListener('click', () => {\n          this.renderDojoMenu();\n          this.showScreen('dojoMenu');\n        });\n        document.getElementById('btnDojoBack').addEventListener('click', () => {\n          this.showScreen('mainMenu');\n        });\n        \n        const tabBlades = document.getElementById('tabBlades');\n        const tabStats = document.getElementById('tabStats');\n        const contentBlades = document.getElementById('dojoContentBlades');\n        const contentStats = document.getElementById('dojoContentStats');\n\n        tabBlades.addEventListener('click', () => {\n          tabBlades.classList.add('active');\n          tabStats.classList.remove('active');\n          contentBlades.classList.remove('hidden');\n          contentStats.classList.add('hidden');\n        });\n\n        tabStats.addEventListener('click', () => {\n          tabStats.classList.add('active');\n          tabBlades.classList.remove('active');\n          contentStats.classList.remove('hidden');\n          contentBlades.classList.add('hidden');\n        });\n\n        const toggle = document.getElementById('toggleSFX');\n        toggle.checked = gameAudio.enabled;\n        toggle.addEventListener('change', (e) => {\n          gameAudio.setEnabled(e.target.checked);\n        });\n\n        document.getElementById('btnResetScore').addEventListener('click', () => {\n          if (confirm('Are you sure you want to delete all saved best scores and stats?')) {\n            this.bestScores = { CLASSIC: 0, ZEN: 0, ARCADE: 0 };\n            this.stats = { totalSliced: 0, totalCombos: 0, maxCombo: 0, totalBombsHit: 0, gamesPlayed: 0 };\n            this.unlockedBlades = ['CLASSIC'];\n            this.selectedBlade = 'CLASSIC';\n            try {\n              localStorage.removeItem('ninja_slice_best_CLASSIC');\n              localStorage.removeItem('ninja_slice_best_ZEN');\n              localStorage.removeItem('ninja_slice_best_ARCADE');\n              localStorage.removeItem('ninja_slice_stats');\n              localStorage.removeItem('ninja_slice_unlocked');\n              localStorage.removeItem('ninja_slice_active_blade');\n            } catch(e) {}\n            this.updateBestScoreDisplay();\n            alert('High scores and dojo stats cleared!');\n          }\n        });\n\n        document.getElementById('pauseButton').addEventListener('click', () => this.pauseGame());\n        document.getElementById('btnResume').addEventListener('click', () => this.resumeGame());\n        document.getElementById('btnRestartPause').addEventListener('click', () => this.startGame(this.gameMode));\n        document.getElementById('btnQuitPause').addEventListener('click', () => this.quitToMenu());\n\n        document.getElementById('btnRestartOver').addEventListener('click', () => this.startGame(this.gameMode));\n        document.getElementById('btnQuitOver').addEventListener('click', () => this.quitToMenu());\n      }\n\n      showScreen(screenId) {\n        const cards = document.querySelectorAll('.menu-card');\n        cards.forEach(c => {\n          c.classList.remove('active');\n          c.classList.add('hidden');\n        });\n        \n        const activeCard = document.getElementById(screenId);\n        if (activeCard) {\n          activeCard.classList.remove('hidden');\n          activeCard.classList.add('active');\n        }\n        \n        const bgGlow = document.querySelector('.title-bg-glow');\n        if (screenId === 'gameOverMenu') {\n          if (bgGlow) bgGlow.style.background = 'var(--color-danger)';\n        } else {\n          if (bgGlow) bgGlow.style.background = 'var(--color-primary)';\n        }\n      }\n\n      setupInputHandlers() {\n        const getPointerPos = (e) => {\n          const rect = this.canvas.getBoundingClientRect();\n          const clientX = e.touches ? e.touches[0].clientX : e.clientX;\n          const clientY = e.touches ? e.touches[0].clientY : e.clientY;\n          return {\n            x: clientX - rect.left,\n            y: clientY - rect.top\n          };\n        };\n\n        const onStart = (e) => {\n          if (this.gameState !== 'PLAYING') return;\n          gameAudio.init();\n          const pos = getPointerPos(e);\n          this.swipe.start(pos.x, pos.y, this.selectedBlade);\n        };\n\n        const onMove = (e) => {\n          if (this.gameState !== 'PLAYING' || !this.swipe.active) return;\n          const pos = getPointerPos(e);\n          \n          if (this.swipe.points.length > 0) {\n            const last = this.swipe.points[this.swipe.points.length - 1];\n            const dx = pos.x - last.x;\n            const dy = pos.y - last.y;\n            if (dx * dx + dy * dy > 25) {\n              this.woodCuts.push({\n                x1: last.x,\n                y1: last.y,\n                x2: pos.x,\n                y2: pos.y,\n                width: 3.5 + Math.random() * 2.0,\n                life: 1200,\n                maxLife: 1200\n              });\n            }\n          }\n          \n          this.swipe.move(pos.x, pos.y, this.particles, this.selectedBlade);\n          this.detectCollisions();\n        };\n\n        const onEnd = () => {\n          this.swipe.end();\n          this.checkAndTriggerCombo();\n        };\n\n        window.addEventListener('mousedown', onStart);\n        window.addEventListener('mousemove', onMove);\n        window.addEventListener('mouseup', onEnd);\n\n        window.addEventListener('touchstart', onStart, { passive: false });\n        window.addEventListener('touchmove', onMove, { passive: false });\n        window.addEventListener('touchend', onEnd, { passive: false });\n      }\n\n      startGame(mode) {\n        gameAudio.init();\n        \n        this.gameState = 'PLAYING';\n        this.gameMode = mode;\n        this.score = 0;\n        this.timeElapsed = 0;\n        this.bombsHitThisGame = 0;\n        \n        this.fruits = [];\n        this.slicedHalves = [];\n        this.bombs = [];\n        this.particles = [];\n        this.splatters = [];\n        this.woodCuts = [];\n        this.swipe.end();\n        this.screenShake = 0;\n        \n        this.blitzFreeze = 0;\n        this.blitzFrenzy = 0;\n        this.blitzDouble = 0;\n        this.launchInterval = MIN_LAUNCH_INTERVAL;\n        this.lastLaunchTime = Date.now();\n        \n        document.getElementById('hud').classList.remove('hidden');\n        document.getElementById('scoreValue').innerText = '0';\n        \n        const livesNode = document.getElementById('livesContainer');\n        const timerNode = document.getElementById('timerContainer');\n        \n        if (mode === 'CLASSIC') {\n          this.lives = 3;\n          livesNode.style.display = 'flex';\n          timerNode.classList.add('hidden');\n          this.renderHearts();\n        } else if (mode === 'ZEN') {\n          this.lives = 0;\n          this.timer = 90000;\n          livesNode.style.display = 'none';\n          timerNode.classList.remove('hidden');\n          this.updateTimerDisplay();\n        } else if (mode === 'ARCADE') {\n          this.lives = 0;\n          this.timer = 60000;\n          livesNode.style.display = 'none';\n          timerNode.classList.remove('hidden');\n          this.updateTimerDisplay();\n        }\n        \n        document.getElementById('overlayContainer').style.pointerEvents = 'none';\n        this.showScreen('hidden');\n      }\n\n      pauseGame() {\n        if (this.gameState !== 'PLAYING') return;\n        this.gameState = 'PAUSED';\n        this.bombs.forEach(b => b.stopFuseSound());\n        \n        document.getElementById('overlayContainer').style.pointerEvents = 'auto';\n        this.showScreen('pauseMenu');\n      }\n\n      resumeGame() {\n        if (this.gameState !== 'PAUSED') return;\n        this.gameState = 'PLAYING';\n        this.bombs.forEach(b => b.startFuseSound());\n        \n        document.getElementById('overlayContainer').style.pointerEvents = 'none';\n        this.showScreen('hidden');\n      }\n\n      quitToMenu() {\n        this.gameState = 'MENU';\n        this.bombs.forEach(b => b.stopFuseSound());\n        \n        document.getElementById('hud').classList.add('hidden');\n        document.getElementById('overlayContainer').style.pointerEvents = 'auto';\n        this.updateBestScoreDisplay();\n        this.showScreen('mainMenu');\n      }\n\n      endGame() {\n        this.gameState = 'GAMEOVER';\n        this.swipe.end();\n        this.bombs.forEach(b => b.stopFuseSound());\n        \n        const newBest = this.saveHighScore(this.gameMode, this.score);\n        \n        this.stats.gamesPlayed++;\n        this.saveStats();\n        \n        const gameEndInfo = {\n          mode: this.gameMode,\n          score: this.score,\n          bombsHit: this.bombsHitThisGame\n        };\n        this.checkAchievements(gameEndInfo);\n        \n        document.getElementById('finalScoreVal').innerText = this.score;\n        document.getElementById('gameOverMode').innerText = this.gameMode.toUpperCase() + ' MODE';\n        \n        const bestBadge = document.getElementById('newBestBadge');\n        if (newBest) {\n          bestBadge.classList.remove('hidden');\n        } else {\n          bestBadge.classList.add('hidden');\n        }\n        \n        document.getElementById('overlayContainer').style.pointerEvents = 'auto';\n        this.showScreen('gameOverMenu');\n      }\n\n      renderHearts() {\n        const hearts = document.querySelectorAll('.heart');\n        hearts.forEach((h, index) => {\n          if (index < this.lives) {\n            h.className = 'heart active';\n          } else {\n            h.className = 'heart lost';\n          }\n        });\n      }\n\n      saveStats() {\n        try {\n          localStorage.setItem('ninja_slice_stats', JSON.stringify(this.stats));\n        } catch(e) {}\n      }\n\n      saveUnlockedBlades() {\n        try {\n          localStorage.setItem('ninja_slice_unlocked', JSON.stringify(this.unlockedBlades));\n        } catch(e) {}\n      }\n\n      equipBlade(bladeId) {\n        if (!this.unlockedBlades.includes(bladeId)) return;\n        this.selectedBlade = bladeId;\n        try {\n          localStorage.setItem('ninja_slice_active_blade', bladeId);\n        } catch(e) {}\n        this.renderDojoMenu();\n      }\n\n      checkAchievements(gameEndInfo = {}) {\n        let unlockedAny = false;\n        \n        if (!this.unlockedBlades.includes('FIRE') && this.stats.totalSliced >= 100) {\n          this.unlockedBlades.push('FIRE');\n          unlockedAny = true;\n          setTimeout(() => this.showAchievementUnlock('FIRE'), 500);\n        }\n\n        if (!this.unlockedBlades.includes('RAINBOW') && this.stats.maxCombo >= 5) {\n          this.unlockedBlades.push('RAINBOW');\n          unlockedAny = true;\n          setTimeout(() => this.showAchievementUnlock('RAINBOW'), 1200);\n        }\n\n        if (!this.unlockedBlades.includes('ICE') && this.bestScores.ZEN >= 150) {\n          this.unlockedBlades.push('ICE');\n          unlockedAny = true;\n          setTimeout(() => this.showAchievementUnlock('ICE'), 500);\n        }\n\n        if (!this.unlockedBlades.includes('SHADOW')) {\n          if (gameEndInfo.mode === 'ARCADE' && gameEndInfo.score >= 80 && gameEndInfo.bombsHit === 0) {\n            this.unlockedBlades.push('SHADOW');\n            unlockedAny = true;\n            setTimeout(() => this.showAchievementUnlock('SHADOW'), 500);\n          }\n        }\n\n        if (unlockedAny) {\n          this.saveUnlockedBlades();\n        }\n      }\n\n      showAchievementUnlock(bladeId) {\n        const info = BLADES[bladeId];\n        this.showTextIndicator(this.width / 2, this.height * 0.45, `🏆 UNLOCKED: ${info.name}!`, '#fbbf24', 1.8);\n      }\n\n      drawDojoBackground() {\n        const ctx = this.ctx;\n        const w = this.width;\n        const h = this.height;\n\n        ctx.fillStyle = '#1e100a';\n        ctx.fillRect(0, 0, w, h);\n\n        const plankWidth = 120;\n        const count = Math.ceil(w / plankWidth);\n        for (let i = 0; i < count; i++) {\n          const px = i * plankWidth;\n          const grad = ctx.createLinearGradient(px, 0, px + plankWidth, 0);\n          if (i % 2 === 0) {\n            grad.addColorStop(0, '#2b170e');\n            grad.addColorStop(0.5, '#351c11');\n            grad.addColorStop(1, '#25140c');\n          } else {\n            grad.addColorStop(0, '#21110a');\n            grad.addColorStop(0.5, '#2e1910');\n            grad.addColorStop(1, '#1f1009');\n          }\n          ctx.fillStyle = grad;\n          ctx.fillRect(px, 0, plankWidth, h);\n\n          ctx.strokeStyle = 'rgba(12, 6, 2, 0.45)';\n          ctx.lineWidth = 2;\n          ctx.beginPath();\n          ctx.moveTo(px, 0);\n          ctx.lineTo(px, h);\n          ctx.stroke();\n\n          ctx.strokeStyle = 'rgba(255, 255, 255, 0.015)';\n          ctx.lineWidth = 1;\n          ctx.beginPath();\n          ctx.moveTo(px + 1.5, 0);\n          ctx.lineTo(px + 1.5, h);\n          ctx.stroke();\n\n          ctx.strokeStyle = 'rgba(255, 255, 255, 0.006)';\n          ctx.lineWidth = 1.5;\n          ctx.save();\n          ctx.beginPath();\n          ctx.rect(px, 0, plankWidth, h);\n          ctx.clip();\n          \n          const grainCount = 3;\n          for (let g = 0; g < grainCount; g++) {\n            const gx = px + (plankWidth / grainCount) * g + Math.sin(g) * 12;\n            ctx.beginPath();\n            ctx.moveTo(gx, 0);\n            ctx.bezierCurveTo(gx - 20, h * 0.35, gx + 20, h * 0.65, gx - 10, h);\n            ctx.stroke();\n          }\n          ctx.restore();\n        }\n\n        this.drawWoodCuts();\n\n        const radialGrad = ctx.createRadialGradient(\n          w / 2, h / 2, Math.min(w, h) * 0.35,\n          w / 2, h / 2, Math.max(w, h) * 0.85\n        );\n        radialGrad.addColorStop(0, 'rgba(0, 0, 0, 0.0)');\n        radialGrad.addColorStop(1, 'rgba(0, 0, 0, 0.65)');\n        ctx.fillStyle = radialGrad;\n        ctx.fillRect(0, 0, w, h);\n      }\n\n      drawWoodCuts() {\n        const ctx = this.ctx;\n        ctx.save();\n        this.woodCuts.forEach(cut => {\n          const progress = cut.life / cut.maxLife;\n          \n          ctx.strokeStyle = `rgba(12, 5, 2, ${progress * 0.75})`;\n          ctx.lineWidth = cut.width;\n          ctx.lineCap = 'round';\n          ctx.beginPath();\n          ctx.moveTo(cut.x1, cut.y1);\n          ctx.lineTo(cut.x2, cut.y2);\n          ctx.stroke();\n\n          ctx.strokeStyle = `rgba(255, 255, 255, ${progress * 0.045})`;\n          ctx.lineWidth = cut.width * 0.4;\n          ctx.lineCap = 'round';\n          ctx.beginPath();\n          ctx.moveTo(cut.x1 + 1, cut.y1 + 1);\n          ctx.lineTo(cut.x2 + 1, cut.y2 + 1);\n          ctx.stroke();\n        });\n        ctx.restore();\n      }\n\n      renderDojoMenu() {\n        const bladesContainer = document.getElementById('dojoContentBlades');\n        bladesContainer.innerHTML = '';\n        \n        Object.keys(BLADES).forEach(bladeId => {\n          const blade = BLADES[bladeId];\n          const isUnlocked = this.unlockedBlades.includes(bladeId);\n          const isEquipped = this.selectedBlade === bladeId;\n          \n          const item = document.createElement('div');\n          item.className = `blade-item ${isEquipped ? 'selected' : ''}`;\n          \n          let btnHtml = '';\n          if (isEquipped) {\n            btnHtml = `<button class=\"blade-action-btn equipped\" disabled>EQUIPPED</button>`;\n          } else if (isUnlocked) {\n            btnHtml = `<button class=\"blade-action-btn equip\" onclick=\"window.gameEngine.equipBlade('${bladeId}')\">EQUIP</button>`;\n          } else {\n            btnHtml = `<button class=\"blade-action-btn locked\" disabled>LOCKED</button>`;\n          }\n          \n          let previewStyle = `background: ${blade.shadowColor}18; color: ${blade.color === 'rainbow' ? '#facc15' : blade.color}; border: 1px solid ${blade.shadowColor}40;`;\n          if (blade.color === 'rainbow') {\n            previewStyle = `background: linear-gradient(135deg, rgba(239,68,68,0.15) 0%, rgba(59,130,246,0.15) 100%); border: 1px solid rgba(255,255,255,0.15);`;\n          }\n          \n          item.innerHTML = `\n            <div class=\"blade-icon-preview\" style=\"${previewStyle}\">\n              ${blade.icon}\n            </div>\n            <div class=\"blade-details\">\n              <div class=\"blade-name\">\n                ${blade.name} \n                ${isEquipped ? '<span style=\"font-size: 0.65rem; background: var(--color-primary); color: #fff; padding: 2px 6px; border-radius: 8px;\">Active</span>' : ''}\n              </div>\n              <div class=\"blade-desc\">${blade.desc}</div>\n              ${!isUnlocked ? `<div class=\"blade-unlock\">🔒 ${blade.unlockDesc}</div>` : ''}\n            </div>\n            ${btnHtml}\n          `;\n          \n          bladesContainer.appendChild(item);\n        });\n\n        const statsContainer = document.getElementById('dojoContentStats');\n        statsContainer.innerHTML = `\n          <div class=\"stat-row\">\n            <span class=\"stat-label\">Total Slices</span>\n            <span class=\"stat-value\">${this.stats.totalSliced}</span>\n          </div>\n          <div class=\"stat-row\">\n            <span class=\"stat-label\">Total Combos</span>\n            <span class=\"stat-value\">${this.stats.totalCombos}</span>\n          </div>\n          <div class=\"stat-row\">\n            <span class=\"stat-label\">Max Combo</span>\n            <span class=\"stat-value\">${this.stats.maxCombo} Fruit Combo</span>\n          </div>\n          <div class=\"stat-row\">\n            <span class=\"stat-label\">Bombs Detonated</span>\n            <span class=\"stat-value\">${this.stats.totalBombsHit}</span>\n          </div>\n          <div class=\"stat-row\">\n            <span class=\"stat-label\">Games Played</span>\n            <span class=\"stat-value\">${this.stats.gamesPlayed}</span>\n          </div>\n          <div class=\"stat-row\" style=\"margin-top: 8px; border-top: 1px dashed rgba(255,255,255,0.1); padding-top: 12px;\">\n            <span class=\"stat-label\">Best Classic Score</span>\n            <span class=\"stat-value\" style=\"color: #facc15;\">${this.bestScores.CLASSIC}</span>\n          </div>\n          <div class=\"stat-row\">\n            <span class=\"stat-label\">Best Arcade Score</span>\n            <span class=\"stat-value\" style=\"color: #ec4899;\">${this.bestScores.ARCADE}</span>\n          </div>\n          <div class=\"stat-row\">\n            <span class=\"stat-label\">Best Zen Score</span>\n            <span class=\"stat-value\" style=\"color: #06b6d4;\">${this.bestScores.ZEN}</span>\n          </div>\n        `;\n      }\n\n      updateTimerDisplay() {\n        const seconds = Math.max(0, Math.ceil(this.timer / 1000));\n        document.getElementById('timerValue').innerText = seconds;\n      }\n\n      throwWave() {\n        const isFreeze = this.blitzFreeze > 0;\n        const roll = Math.random();\n        let count = 1;\n        \n        if (roll > 0.85) count = 3;\n        else if (roll > 0.45) count = 2;\n        \n        if (this.fruits.length + this.bombs.length + count > MAX_FRUITS_ON_SCREEN) {\n          count = Math.max(1, MAX_FRUITS_ON_SCREEN - (this.fruits.length + this.bombs.length));\n        }\n        \n        for (let i = 0; i < count; i++) {\n          this.spawnStandardObject();\n        }\n      }\n\n      spawnStandardObject() {\n        const x = 80 + Math.random() * (this.width - 160);\n        const y = this.height + 40;\n        \n        const targetX = this.width / 2 + (Math.random() - 0.5) * (this.width * 0.4);\n        const targetY = this.height * 0.15 + Math.random() * (this.height * 0.35);\n        \n        const gravityValue = GRAVITY;\n        const peakHeight = y - targetY;\n        const timeToPeak = Math.sqrt((2 * peakHeight) / gravityValue);\n        \n        const vy = -gravityValue * timeToPeak;\n        const vx = (targetX - x) / timeToPeak;\n        \n        let objectRoll = Math.random();\n        const bombThreshold = this.gameMode === 'CLASSIC' ? 0.22 : (this.gameMode === 'ARCADE' ? 0.16 : 0.0);\n        \n        if (objectRoll < bombThreshold) {\n          const b = new Bomb(x, y, vx, vy);\n          b.startFuseSound();\n          this.bombs.push(b);\n        } else {\n          let isBlitz = false;\n          let fruitType = 'WATERMELON';\n          \n          if (this.gameMode === 'ARCADE' && Math.random() < 0.12) {\n            isBlitz = true;\n            const keys = Object.keys(BLITZ_TYPES);\n            fruitType = keys[Math.floor(Math.random() * keys.length)];\n            gameAudio.playBlitzSpawn();\n          } else {\n            const keys = Object.keys(FRUIT_TYPES);\n            fruitType = keys[Math.floor(Math.random() * keys.length)];\n          }\n          \n          this.fruits.push(new Fruit(x, y, vx, vy, fruitType, isBlitz));\n        }\n      }\n\n      spawnFrenzyFruit() {\n        const leftSide = Math.random() < 0.5;\n        const x = leftSide ? -30 : this.width + 30;\n        const y = this.height * 0.3 + Math.random() * (this.height * 0.4);\n        \n        const vx = leftSide ? (6 + Math.random() * 5) : -(6 + Math.random() * 5);\n        const vy = -4 - Math.random() * 5;\n        \n        const keys = Object.keys(FRUIT_TYPES);\n        const fruitType = keys[Math.floor(Math.random() * keys.length)];\n        this.fruits.push(new Fruit(x, y, vx, vy, fruitType, false));\n      }\n\n      detectCollisions() {\n        if (this.swipe.points.length < 2) return;\n        \n        const p2 = this.swipe.points[this.swipe.points.length - 1];\n        const p1 = this.swipe.points[this.swipe.points.length - 2];\n        \n        this.fruits.forEach(f => {\n          if (f.sliced) return;\n          const dist = getDistPointToSegment(f.x, f.y, p1.x, p1.y, p2.x, p2.y);\n          if (dist < f.radius) {\n            this.sliceFruit(f, p1, p2);\n          }\n        });\n        \n        this.bombs.forEach(b => {\n          if (b.sliced) return;\n          const dist = getDistPointToSegment(b.x, b.y, p1.x, p1.y, p2.x, p2.y);\n          if (dist < b.radius) {\n            this.detonateBomb(b);\n          }\n        });\n      }\n\n      sliceFruit(fruit, p1, p2) {\n        fruit.sliced = true;\n        \n        const sliceDist = getDistPointToSegment(fruit.x, fruit.y, p1.x, p1.y, p2.x, p2.y);\n        const isCritical = !fruit.isBlitz && (sliceDist < 3.2 || Math.random() < 0.05);\n        \n        if (isCritical) {\n          gameAudio.playCritical();\n          this.screenFlash = 120;\n          this.screenShake = 5.0;\n          this.score += 10;\n          document.getElementById('scoreValue').innerText = this.score;\n          this.showTextIndicator(fruit.x, fruit.y, 'CRITICAL! +10', '#facc15', 1.6);\n        } else {\n          gameAudio.playSplat(this.selectedBlade);\n          this.screenShake = 1.4;\n        }\n\n        this.stats.totalSliced++;\n        \n        const sliceAngle = Math.atan2(p2.y - p1.y, p2.x - p1.x);\n        const pushForce = 2.2 + Math.random() * 1.5;\n        const pushAngleL = sliceAngle - Math.PI / 2;\n        const pushAngleR = sliceAngle + Math.PI / 2;\n        \n        const vxl = fruit.vx + Math.cos(pushAngleL) * pushForce;\n        const vyl = fruit.vy + Math.sin(pushAngleL) * pushForce - 1.5;\n        const vxr = fruit.vx + Math.cos(pushAngleR) * pushForce;\n        const vyr = fruit.vy + Math.sin(pushAngleR) * pushForce - 1.5;\n        \n        this.slicedHalves.push(\n          new SlicedHalf(fruit.x, fruit.y, vxl, vyl, sliceAngle, fruit.spin, fruit.radius, fruit.type, fruit.isBlitz),\n          new SlicedHalf(fruit.x, fruit.y, vxr, vyr, sliceAngle, fruit.spin, fruit.radius, fruit.type, fruit.isBlitz)\n        );\n        \n        const particleColor = isCritical ? '#facc15' : fruit.color;\n        const burstCount = isCritical ? (24 + Math.floor(Math.random() * 12)) : (12 + Math.floor(Math.random() * 8));\n        \n        for (let i = 0; i < burstCount; i++) {\n          const sprayAngle = Math.random() * Math.PI * 2;\n          const speed = isCritical ? (5 + Math.random() * 10) : (3 + Math.random() * 6);\n          this.particles.push(new PhysicsParticle(\n            fruit.x, fruit.y,\n            Math.cos(sprayAngle) * speed + fruit.vx * 0.5,\n            Math.sin(sprayAngle) * speed + fruit.vy * 0.5,\n            particleColor,\n            2 + Math.random() * 3.5,\n            'juice',\n            this.selectedBlade\n          ));\n        }\n        \n        if (Math.random() < 0.8) {\n          this.splatters.push(new JuiceSplatter(fruit.x, fruit.y, isCritical ? '#fef08a' : fruit.color));\n        }\n        \n        if (fruit.isBlitz) {\n          this.activateBlitz(fruit.type);\n        } else {\n          let slicePoints = 1;\n          if (this.blitzDouble > 0) slicePoints = 2;\n          \n          if (!isCritical) {\n            this.score += slicePoints;\n            document.getElementById('scoreValue').innerText = this.score;\n          }\n          \n          this.comboCount++;\n          this.lastSliceTime = Date.now();\n          this.currentComboFruits.push({ x: fruit.x, y: fruit.y });\n        }\n      }\n\n      detonateBomb(bomb) {\n        bomb.sliced = true;\n        bomb.stopFuseSound();\n        gameAudio.playExplosion();\n        \n        this.screenFlash = 255;\n        this.screenShake = 18;\n        this.bombsHitThisGame++;\n        this.stats.totalBombsHit++;\n        \n        for (let i = 0; i < 40; i++) {\n          const angle = Math.random() * Math.PI * 2;\n          const speed = 4 + Math.random() * 12;\n          this.particles.push(new PhysicsParticle(\n            bomb.x, bomb.y,\n            Math.cos(angle) * speed,\n            Math.sin(angle) * speed,\n            Math.random() < 0.6 ? '#f59e0b' : '#ef4444',\n            3 + Math.random() * 5,\n            'juice',\n            this.selectedBlade\n          ));\n        }\n        \n        if (this.gameMode === 'CLASSIC') {\n          this.lives = 0;\n          this.renderHearts();\n          setTimeout(() => this.endGame(), 400);\n        } else if (this.gameMode === 'ARCADE') {\n          this.score = Math.max(0, this.score - 10);\n          document.getElementById('scoreValue').innerText = this.score;\n          this.showTextIndicator(bomb.x, bomb.y, '-10', '#ef4444');\n        }\n      }\n\n      activateBlitz(type) {\n        if (type === 'FREEZE') {\n          this.blitzFreeze = 6000;\n        } else if (type === 'FRENZY') {\n          this.blitzFrenzy = 6000;\n          this.frenzySpawnTimer = 0;\n        } else if (type === 'DOUBLE') {\n          this.blitzDouble = 6000;\n        }\n        this.showTextIndicator(this.width / 2, this.height * 0.33, `${type} MODE!`, BLITZ_TYPES[type].color, 2.0);\n      }\n\n      checkAndTriggerCombo() {\n        if (this.comboCount >= 3) {\n          this.stats.totalCombos++;\n          if (this.comboCount > this.stats.maxCombo) {\n            this.stats.maxCombo = this.comboCount;\n          }\n          this.saveStats();\n          \n          let comboBonus = this.comboCount;\n          if (this.blitzDouble > 0) comboBonus *= 2;\n          \n          this.score += comboBonus;\n          document.getElementById('scoreValue').innerText = this.score;\n          \n          let avgX = 0, avgY = 0;\n          this.currentComboFruits.forEach(f => {\n            avgX += f.x;\n            avgY += f.y;\n          });\n          avgX /= this.currentComboFruits.length;\n          avgY /= this.currentComboFruits.length;\n          \n          gameAudio.playCombo(this.comboCount);\n          this.announceCombo(this.comboCount);\n          this.showTextIndicator(avgX, avgY, `${this.comboCount} COMBO! +${comboBonus}`, '#fbbf24', 1.5);\n          this.screenShake = 6.0 + this.comboCount * 0.5;\n        }\n        \n        this.comboCount = 0;\n        this.currentComboFruits = [];\n      }\n\n      announceCombo(count) {\n        const ann = document.getElementById('comboAnnouncer');\n        ann.innerText = `${count} FRUIT COMBO!`;\n        ann.className = 'pop';\n        \n        setTimeout(() => {\n          ann.className = '';\n        }, 1200);\n      }\n\n      showTextIndicator(x, y, text, color, scale = 1.0) {\n        this.particles.push({\n          x, y,\n          vx: 0,\n          vy: -1.2,\n          color,\n          size: 0,\n          text,\n          scale,\n          alpha: 1.0,\n          decay: 0.02,\n          update(dt) {\n            this.y += this.vy * dt;\n            this.alpha -= this.decay * dt;\n            return this.alpha > 0;\n          },\n          draw(ctx) {\n            ctx.save();\n            ctx.globalAlpha = this.alpha;\n            ctx.fillStyle = this.color;\n            ctx.shadowBlur = 6;\n            ctx.shadowColor = 'rgba(0,0,0,0.8)';\n            ctx.font = `800 ${Math.floor(18 * this.scale)}px 'Outfit', sans-serif`;\n            ctx.textAlign = 'center';\n            ctx.fillText(this.text, this.x, this.y);\n            ctx.restore();\n          }\n        });\n      }\n\n      loop(timestamp) {\n        let dt = (timestamp - this.lastTime) / 16.666;\n        if (dt > 4) dt = 4;\n        this.lastTime = timestamp;\n        \n        this.update(dt);\n        this.draw();\n        \n        requestAnimationFrame((t) => this.loop(t));\n      }\n\n      update(dt) {\n        if (this.gameState !== 'PLAYING') {\n          this.swipe.update();\n          this.woodCuts = this.woodCuts.filter(cut => {\n            cut.life -= dt * 16.666;\n            return cut.life > 0;\n          });\n          return;\n        }\n        \n        if (this.screenShake > 0) {\n          this.screenShake = Math.max(0, this.screenShake - 0.8 * dt);\n        }\n        \n        this.woodCuts = this.woodCuts.filter(cut => {\n          cut.life -= dt * 16.666;\n          return cut.life > 0;\n        });\n        \n        let physicsDt = dt;\n        if (this.blitzFreeze > 0) {\n          physicsDt = dt * 0.35;\n          this.blitzFreeze = Math.max(0, this.blitzFreeze - dt * 16.666);\n        }\n        \n        if (this.blitzFrenzy > 0) {\n          this.blitzFrenzy = Math.max(0, this.blitzFrenzy - dt * 16.666);\n        }\n        if (this.blitzDouble > 0) {\n          this.blitzDouble = Math.max(0, this.blitzDouble - dt * 16.666);\n        }\n        \n        if (this.comboCount > 0 && Date.now() - this.lastSliceTime > 300) {\n          this.checkAndTriggerCombo();\n        }\n        \n        if (this.gameMode === 'ZEN' || this.gameMode === 'ARCADE') {\n          this.timer -= dt * 16.666;\n          this.updateTimerDisplay();\n          if (this.timer <= 0) {\n            this.endGame();\n            return;\n          }\n        }\n        \n        this.splatters = this.splatters.filter(s => s.update(dt));\n        this.slicedHalves = this.slicedHalves.filter(h => h.update(physicsDt));\n        \n        this.fruits = this.fruits.filter(f => {\n          const active = f.update(physicsDt);\n          if (!active && !f.sliced) {\n            if (this.gameMode === 'CLASSIC' && !f.isBlitz) {\n              this.lives--;\n              this.renderHearts();\n              if (this.lives <= 0) {\n                this.endGame();\n              }\n            }\n          }\n          return active && !f.sliced;\n        });\n        \n        this.bombs = this.bombs.filter(b => {\n          const active = b.update(physicsDt, this.particles);\n          if (!active || b.sliced) {\n            b.stopFuseSound();\n          }\n          return active && !b.sliced;\n        });\n        \n        this.particles = this.particles.filter(p => p.update(dt));\n        this.swipe.update();\n        \n        const now = Date.now();\n        if (this.blitzFrenzy > 0) {\n          this.frenzySpawnTimer += dt * 16.666;\n          if (this.frenzySpawnTimer > 280) {\n            this.spawnFrenzyFruit();\n            this.frenzySpawnTimer = 0;\n          }\n        } else {\n          const timeThreshold = this.blitzFreeze > 0 ? this.launchInterval * 1.5 : this.launchInterval;\n          if (now - this.lastLaunchTime > timeThreshold) {\n            this.throwWave();\n            this.lastLaunchTime = now;\n            \n            if (this.gameMode !== 'ZEN') {\n              this.timeElapsed += dt;\n              this.launchInterval = Math.max(450, MIN_LAUNCH_INTERVAL - (this.timeElapsed * 1.5));\n            }\n          }\n        }\n        \n        if (this.screenFlash > 0) {\n          this.screenFlash = Math.max(0, this.screenFlash - 8 * dt);\n        }\n      }\n\n      draw() {\n        this.ctx.save();\n        if (this.screenShake > 0) {\n          const dx = (Math.random() - 0.5) * this.screenShake;\n          const dy = (Math.random() - 0.5) * this.screenShake;\n          this.ctx.translate(dx, dy);\n        }\n\n        this.drawDojoBackground();\n        this.drawArcadePowerFilters();\n        this.splatters.forEach(s => s.draw(this.ctx));\n        this.slicedHalves.forEach(h => h.draw(this.ctx));\n        this.fruits.forEach(f => f.draw(this.ctx));\n        this.bombs.forEach(b => b.draw(this.ctx));\n        this.particles.forEach(p => p.draw(this.ctx));\n        this.swipe.draw(this.ctx);\n        \n        if (this.screenFlash > 0) {\n          this.ctx.save();\n          if (this.screenShake > 10) {\n            this.ctx.fillStyle = `rgba(239, 68, 68, ${this.screenFlash / 255})`;\n          } else {\n            this.ctx.fillStyle = `rgba(255, 255, 255, ${this.screenFlash / 255})`;\n          }\n          this.ctx.fillRect(0, 0, this.width, this.height);\n          this.ctx.restore();\n        }\n        this.ctx.restore();\n      }\n\n      drawArcadePowerFilters() {\n        if (this.gameState !== 'PLAYING') return;\n        \n        if (this.blitzFreeze > 0) {\n          const grad = this.ctx.createRadialGradient(\n            this.width/2, this.height/2, this.width*0.2, \n            this.width/2, this.height/2, this.width*0.75\n          );\n          grad.addColorStop(0, 'rgba(6, 182, 212, 0.0)');\n          grad.addColorStop(1, 'rgba(6, 182, 212, 0.12)');\n          this.ctx.fillStyle = grad;\n          this.ctx.fillRect(0, 0, this.width, this.height);\n          this.drawBlitzLabel(\"FREEZE ACTIVE\", '#06b6d4', this.blitzFreeze);\n        }\n        \n        if (this.blitzFrenzy > 0) {\n          const grad = this.ctx.createRadialGradient(\n            this.width/2, this.height/2, this.width*0.2, \n            this.width/2, this.height/2, this.width*0.75\n          );\n          grad.addColorStop(0, 'rgba(236, 72, 153, 0.0)');\n          grad.addColorStop(1, 'rgba(236, 72, 153, 0.12)');\n          this.ctx.fillStyle = grad;\n          this.ctx.fillRect(0, 0, this.width, this.height);\n          this.drawBlitzLabel(\"FRENZY ACTIVE\", '#ec4899', this.blitzFrenzy, this.blitzFreeze > 0 ? 30 : 0);\n        }\n        \n        if (this.blitzDouble > 0) {\n          const grad = this.ctx.createRadialGradient(\n            this.width/2, this.height/2, this.width*0.2, \n            this.width/2, this.height/2, this.width*0.75\n          );\n          grad.addColorStop(0, 'rgba(168, 85, 247, 0.0)');\n          grad.addColorStop(1, 'rgba(168, 85, 247, 0.12)');\n          this.ctx.fillStyle = grad;\n          this.ctx.fillRect(0, 0, this.width, this.height);\n          \n          const verticalOffset = (this.blitzFreeze > 0 ? 30 : 0) + (this.blitzFrenzy > 0 ? 30 : 0);\n          this.drawBlitzLabel(\"DOUBLE POINTS\", '#a855f7', this.blitzDouble, verticalOffset);\n        }\n      }\n\n      drawBlitzLabel(label, color, timeLeftMs, verticalOffset = 0) {\n        this.ctx.save();\n        this.ctx.fillStyle = color;\n        this.ctx.font = \"800 12px 'Outfit', sans-serif\";\n        this.ctx.textAlign = \"center\";\n        this.ctx.shadowBlur = 4;\n        this.ctx.shadowColor = color;\n        \n        const secs = (timeLeftMs / 1000).toFixed(1);\n        this.ctx.fillText(`${label} - ${secs}s`, this.width / 2, 95 + verticalOffset);\n        this.ctx.restore();\n      }\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      window.gameEngine = new NinjaSliceGame();\n    });\n  </script>\n</body>\n</html>\n";